/**
 * ContactTrigger
 *
 * Bulk-safe entry point. Contains no SOQL and no DML - all work is delegated
 * to ContactTriggerHandler so that a single query/DML statement can serve the
 * whole trigger context (up to 200 contacts).
 */
trigger ContactTrigger on Contact (before insert, before update, after insert) {

    // Before contexts: default MailingCountry / LeadSource from the Account.
    if (Trigger.isBefore) {
        ContactTriggerHandler.handleBefore(Trigger.new, Trigger.isInsert);
    }

    // After insert: seed the Account.Phone from the first new Contact that has one.
    if (Trigger.isAfter && Trigger.isInsert) {
        ContactTriggerHandler.handleAfterInsert(Trigger.new);
    }
}
