/**
 * Thin, bulk-safe client for the FX provider exposed through the
 * Named Credential `FB_Exchange_Rates`.
 *
 * GET callout:FB_Exchange_Rates/v1/latest?base=EUR&symbols=USD,GBP
 * ->
 * {"base":"EUR","date":"2026-09-25","rates":{"USD":1.1234,"GBP":0.8412}}
 *
 * Rules implemented here:
 *  - every currency code is trimmed and upper-cased before use;
 *  - invalid input (bad code / null-or-empty quote set) fails fast,
 *    before any callout is issued;
 *  - exactly one HTTP GET per invocation, retried once only on 503;
 *  - any non-200 final status raises ExchangeRateException carrying
 *    the numeric status code;
 *  - only the requested (normalised) codes are returned; extra rates
 *    in the payload are ignored, missing ones are an error.
 */
public with sharing class ExchangeRateClient {

    /** Raised for invalid input, transport/status failures and bad payloads. */
    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT      = 'callout:FB_Exchange_Rates/v1/latest';
    private static final String HTTP_GET      = 'GET';
    private static final String ACCEPT_HEADER = 'Accept';
    private static final String ACCEPT_JSON   = 'application/json';

    private static final Integer STATUS_OK                = 200;
    private static final Integer STATUS_SERVICE_UNAVAILABLE = 503;
    private static final Integer CALLOUT_TIMEOUT_MS       = 20000;

    private static final String CODE_REGEX = '^[A-Z]{3}$';

    /**
     * Fetches the latest FX rates for the requested quote currencies.
     *
     * @param baseCurrency   base currency code, e.g. ' eur ' -> 'EUR'
     * @param quoteCurrencies set of quote codes, e.g. {'usd', 'gbp'}
     * @return map keyed by every normalised requested code
     * @throws ExchangeRateException on invalid input, non-200 response,
     *                               unparseable body or missing rate
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {

        // ------------------------------------------------------------------
        // 1. Normalise + validate everything up-front (no callout on bad input)
        // ------------------------------------------------------------------
        String base = normalize(baseCurrency, 'base currency');

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        List<String> quotes = new List<String>();
        for (String candidate : quoteCurrencies) {
            String code = normalize(candidate, 'quote currency');
            if (!quotes.contains(code)) {          // 'usd' + 'USD' collapse to one code
                quotes.add(code);
            }
        }
        quotes.sort();                              // deterministic query string

        String url = ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(base, 'UTF-8')
            + '&symbols=' + encodeAndJoin(quotes);

        // ------------------------------------------------------------------
        // 2. One GET, retried once (identical request) when the status is 503
        // ------------------------------------------------------------------
        HttpResponse response = null;
        try {
            response = send(buildRequest(url));
            if (response.getStatusCode() == STATUS_SERVICE_UNAVAILABLE) {
                response = send(buildRequest(url));   // identical request, single retry
            }
        } catch (CalloutException ce) {
            throw new ExchangeRateException(
                'Callout to the FX provider failed before a status was received: ' + ce.getMessage());
        }

        Integer status = response.getStatusCode();
        if (status != STATUS_OK) {
            throw new ExchangeRateException(
                'FX provider request failed with HTTP status ' + String.valueOf(status) + '.');
        }

        // ------------------------------------------------------------------
        // 3. Parse the payload for exactly the requested currencies
        // ------------------------------------------------------------------
        return parseRates(response.getBody(), quotes);
    }

    // -----------------------------------------------------------------------
    // Private helpers
    // -----------------------------------------------------------------------

    /** Trim + upper-case, then require exactly three letters A-Z. */
    private static String normalize(String raw, String label) {
        String code = (raw == null) ? '' : raw.trim().toUpperCase();
        if (!isValidCode(code)) {
            throw new ExchangeRateException(
                'Invalid ' + label + ': "' + (raw == null ? '' : raw)
                + '" must be exactly three letters A-Z after trimming and upper-casing.');
        }
        return code;
    }

    private static Boolean isValidCode(String code) {
        if (code == null || code.length() != 3) {
            return false;
        }
        return Pattern.compile(CODE_REGEX).matcher(code).matches();
    }

    /** Percent-encodes each code and joins them with commas: USD,GBP */
    private static String encodeAndJoin(List<String> codes) {
        List<String> encoded = new List<String>();
        for (String code : codes) {
            encoded.add(EncodingUtil.urlEncode(code, 'UTF-8'));
        }
        return String.join(encoded, ',');
    }

    /** A brand-new, byte-for-byte identical request is built for every attempt. */
    private static HttpRequest buildRequest(String url) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(url);
        req.setMethod(HTTP_GET);
        req.setHeader(ACCEPT_HEADER, ACCEPT_JSON);
        req.setTimeout(CALLOUT_TIMEOUT_MS);
        return req;
    }

    private static HttpResponse send(HttpRequest req) {
        return new Http().send(req);
    }

    /** Extracts the requested rates from the response body. */
    private static Map<String, Decimal> parseRates(String body, List<String> quoteCodes) {
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Unable to parse response body: the body is empty.');
        }

        Map<String, Object> payload;
        try {
            payload = (Map<String, Object>) JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse response body: ' + e.getMessage());
        }
        if (payload == null) {
            throw new ExchangeRateException('Unable to parse response body: expected a JSON object.');
        }

        Map<String, Object> rates;
        try {
            rates = (Map<String, Object>) payload.get('rates');
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse response body: "rates" is not an object.');
        }
        if (rates == null) {
            throw new ExchangeRateException('Unable to parse response body: missing "rates" object.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : quoteCodes) {
            Object rawRate = rates.get(code);
            if (rawRate == null) {
                throw new ExchangeRateException('No rate returned for currency ' + code + '.');
            }
            Decimal rate;
            try {
                rate = (rawRate instanceof Decimal)
                    ? (Decimal) rawRate
                    : Decimal.valueOf(String.valueOf(rawRate));
            } catch (Exception e) {
                throw new ExchangeRateException('No numeric rate returned for currency ' + code + '.');
            }
            result.put(code, rate);   // extra rates in the payload are simply ignored
        }
        return result;
    }
}
