/**
 * Utility for interpreting free-text supplier payment terms.
 *
 * Every member is static and stateless, so the class adds no heap, performs no
 * DML or queries, and is safe to call from bulkified triggers, batch workers
 * and queueables without extra governor cost.
 */
public class PaymentTerms {

    /** 'NET' followed by 1-3 digits, with or without whitespace in between. */
    private static final Pattern NET_DAYS_PATTERN = Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');

    /** Free-text term that is payable immediately. */
    private static final String DUE_ON_RECEIPT = 'DUE ON RECEIPT';

    /** Highest number of net days accepted from a supplier. */
    private static final Integer MAX_NET_DAYS = 180;

    /**
     * Converts free-text payment terms into a number of net days.
     *
     * Surrounding whitespace is ignored and matching is case insensitive.
     *
     * @param terms raw payment terms, e.g. 'NET 30', 'net45', 'Due On Receipt'
     * @return the number of net days (0 for 'DUE ON RECEIPT')
     * @throws UnsupportedTermsException when the text cannot be recognised,
     *                                   including null or blank input
     * @throws TermsOutOfRangeException when more than 180 net days are requested
     */
    public static Integer parseNetDays(String terms) {
        if (terms == null) {
            throw unsupportedTerms(null);
        }

        String candidate = terms.trim();

        if (candidate.equalsIgnoreCase(DUE_ON_RECEIPT)) {
            return 0;
        }

        Matcher matcher = NET_DAYS_PATTERN.matcher(candidate);
        if (matcher.matches()) {
            Integer days = Integer.valueOf(matcher.group(1));
            if (days > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }
            return days;
        }

        throw unsupportedTerms(terms);
    }

    /**
     * Calculates the due date of an invoice from its date and payment terms.
     *
     * @param invoiceDate date the supplier invoice was raised
     * @param terms       raw payment terms, e.g. 'NET 30'
     * @return the invoice date plus the net days (null when invoiceDate is null)
     * @throws UnsupportedTermsException when the terms cannot be recognised
     * @throws TermsOutOfRangeException when more than 180 net days are requested
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        if (invoiceDate == null) {
            return null;
        }
        return invoiceDate.addDays(netDays);
    }

    /**
     * Builds the standard 'unsupported terms' error, reporting the input
     * exactly as it was passed in ('null' for a null input).
     */
    private static UnsupportedTermsException unsupportedTerms(String terms) {
        String reported = terms == null ? 'null' : terms;
        return new UnsupportedTermsException('Unsupported payment terms: ' + reported);
    }
}
