/**
 * Server side entry point for the "record finder" Lightning component.
 *
 * Security / correctness model
 * ----------------------------
 *  - The class is declared `with sharing`, so record level visibility of the
 *    running user is always honoured.
 *  - Object CRUD (Read) and field level security are validated up front with
 *    describe metadata, and the dynamic SOQL itself is executed in USER_MODE,
 *    so FLS is enforced a second time by the query engine.
 *  - Object and field API names are only ever emitted into the query after
 *    they have been resolved against describe metadata (a whitelist of names
 *    that Salesforce itself supplied), so user input can never become SOQL
 *    syntax.
 *  - Filter values of any type are always passed as bind variables, never
 *    concatenated, so they can never inject SOQL.
 *  - Every failure mode throws SearchException - no other exception type ever
 *    escapes this class.
 *
 * API version 67.0
 */
public with sharing class RecordSearchService {

    /**
     * The only exception type thrown by this service.
     */
    public class SearchException extends Exception {}

    /** Lowest accepted value for maxRows. */
    private static final Integer MIN_ROWS = 1;
    /** Highest accepted value for maxRows. */
    private static final Integer MAX_ROWS = 200;

    /**
     * Runs a single equality based SOQL search against one object.
     *
     * @param objectApiName API name of the object to search (case insensitive).
     * @param fields        API names of the fields to return (case insensitive); Id is always added.
     * @param filters       Equality filters; one `field = value` condition per entry, combined with AND.
     *                      May be null or empty. Values may be of any type, including null.
     * @param orderByField  API name of the field to sort on ascending; ignored when null/blank.
     * @param maxRows       Maximum number of rows to return, between 1 and 200 (inclusive).
     * @return The matching records, subject to sharing and field level security.
     * @throws SearchException when the request is invalid or not permitted.
     */
    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {

        // -------------------------------------------------------------------
        // 1. Row limit
        // -------------------------------------------------------------------
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'The maximum number of rows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + ' (inclusive).'
            );
        }

        // -------------------------------------------------------------------
        // 2. Object: must exist and the running user must be able to read it
        // -------------------------------------------------------------------
        Schema.SObjectType sObjectType = findObjectType(objectApiName);
        if (sObjectType == null) {
            throw new SearchException('The object \'' + objectApiName + '\' does not exist.');
        }

        Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe();
        String objectName = objectDescribe.getName();
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('You do not have access to the object \'' + objectName + '\'.');
        }

        // -------------------------------------------------------------------
        // 3. Requested output fields (must exist and be readable)
        // -------------------------------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested for object \'' + objectName + '\'.');
        }

        Map<String, Schema.SObjectField> fieldLookup = buildFieldLookup(objectDescribe.fields.getMap());

        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> selectedKeys = new Set<String>{ 'id' };

        for (String requestedField : fields) {
            Schema.DescribeFieldResult fieldDescribe = resolveField(fieldLookup, requestedField, objectName);
            requireReadable(fieldDescribe, objectName);
            // Deduplicate case insensitively so 'Id' / 'Name' are never selected twice.
            if (selectedKeys.add(fieldDescribe.getName().toLowerCase())) {
                selectFields.add(fieldDescribe.getName());
            }
        }

        // -------------------------------------------------------------------
        // 4. WHERE: one equality condition per filter entry, joined with AND
        // -------------------------------------------------------------------
        List<String> conditions = new List<String>();
        Map<String, Object> bindValues = new Map<String, Object>();

        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String requestedFilter : filters.keySet()) {
                Schema.DescribeFieldResult fieldDescribe = resolveField(fieldLookup, requestedFilter, objectName);
                requireReadable(fieldDescribe, objectName);
                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException(
                        'The field \'' + fieldDescribe.getName() + '\' on \'' + objectName + '\' cannot be used in a filter.'
                    );
                }
                // The bind name is generated by this class, so it can never collide
                // with user input, and the value itself is never concatenated.
                String bindName = 'filterValue' + bindIndex;
                bindIndex++;
                conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                bindValues.put(bindName, filters.get(requestedFilter));
            }
        }

        // -------------------------------------------------------------------
        // 5. ORDER BY (ascending) - only when an order field was supplied
        // -------------------------------------------------------------------
        String orderByClause = '';
        if (!String.isBlank(orderByField)) {
            Schema.DescribeFieldResult fieldDescribe = resolveField(fieldLookup, orderByField, objectName);
            requireReadable(fieldDescribe, objectName);
            if (!fieldDescribe.isSortable()) {
                throw new SearchException(
                    'The field \'' + fieldDescribe.getName() + '\' on \'' + objectName + '\' cannot be used in ORDER BY.'
                );
            }
            orderByClause = ' ORDER BY ' + fieldDescribe.getName() + ' ASC';
        }

        // -------------------------------------------------------------------
        // 6. Build the single query. Every identifier written here came from
        //    describe metadata, never directly from the caller.
        // -------------------------------------------------------------------
        String queryString = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objectName;
        if (!conditions.isEmpty()) {
            queryString += ' WHERE ' + String.join(conditions, ' AND ');
        }
        queryString += orderByClause;
        queryString += ' LIMIT ' + maxRows;

        // -------------------------------------------------------------------
        // 7. Execute in USER_MODE (FLS + sharing) with bound filter values.
        // -------------------------------------------------------------------
        try {
            return Database.queryWithBinds(queryString, bindValues, AccessLevel.USER_MODE);
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'RecordSearchService: query failed - ' + e.getMessage());
            throw new SearchException('The record search could not be executed: ' + e.getMessage());
        }
    }

    /**
     * Resolves an object API name to its sObject type, ignoring case.
     * Returns null when the object does not exist.
     */
    private static Schema.SObjectType findObjectType(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            return null;
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sObjectType = globalDescribe.get(objectApiName);
        if (sObjectType != null) {
            return sObjectType;
        }

        // Fall back to an explicit case insensitive lookup.
        String candidate = objectApiName.toLowerCase();
        for (String existingName : globalDescribe.keySet()) {
            if (existingName != null && existingName.toLowerCase() == candidate) {
                return globalDescribe.get(existingName);
            }
        }
        return null;
    }

    /**
     * Builds a case insensitive lookup of field API name -> field token.
     */
    private static Map<String, Schema.SObjectField> buildFieldLookup(Map<String, Schema.SObjectField> describeFields) {
        Map<String, Schema.SObjectField> lookup = new Map<String, Schema.SObjectField>();
        if (describeFields != null) {
            for (String fieldName : describeFields.keySet()) {
                if (fieldName != null) {
                    lookup.put(fieldName.toLowerCase(), describeFields.get(fieldName));
                }
            }
        }
        return lookup;
    }

    /**
     * Resolves a field API name (case insensitive) on the given object and
     * returns its describe. Throws SearchException when the field does not
     * exist on that object.
     */
    private static Schema.DescribeFieldResult resolveField(
        Map<String, Schema.SObjectField> fieldLookup,
        String fieldApiName,
        String objectApiName
    ) {
        Schema.SObjectField fieldToken = null;
        if (!String.isBlank(fieldApiName)) {
            fieldToken = fieldLookup.get(fieldApiName.toLowerCase());
        }
        if (fieldToken == null) {
            throw new SearchException('The field \'' + fieldApiName + '\' does not exist on \'' + objectNameSafe(objectApiName) + '\'.');
        }
        return fieldToken.getDescribe();
    }

    /**
     * Throws SearchException unless the running user may read the field.
     */
    private static void requireReadable(Schema.DescribeFieldResult fieldDescribe, String objectApiName) {
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException(
                'You do not have access to the field \'' + fieldDescribe.getName() + '\' on \'' + objectApiName + '\'.'
            );
        }
    }

    private static String objectNameSafe(String objectApiName) {
        return objectApiName == null ? '' : objectApiName;
    }
}
