/**
 * Flow-invocable action that finds an existing Contact by email address.
 *
 * - Bulk-safe: exactly one SOQL query is issued per invocation, no matter how
 *   many interviews (requests) Flow passes in (up to 200).
 * - Order-safe: exactly one Result is returned per Request, in the same order.
 * - Matching is case-insensitive and ignores leading/trailing spaces in the input.
 * - When several Contacts share the email, the one with the earliest CreatedDate wins.
 * - The class runs "with sharing", so only records visible to the running user
 *   (Flow running user / context user) are returned.
 */
public with sharing class ContactLookupAction {

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing Contact whose email matches the given address (case-insensitive, trimmed).'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // ------------------------------------------------------------------
        // 1. Normalise the inputs (index aligned with the requests) and
        //    collect the distinct, non-blank values to look up.
        // ------------------------------------------------------------------
        List<String> normalizedInputs = new List<String>();
        Set<String> emailsToFind = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            Request req = requests[i];
            String normalized = normalize(req == null ? null : req.email);
            normalizedInputs.add(normalized);
            if (String.isNotBlank(normalized)) {
                emailsToFind.add(normalized);
            }
        }

        // ------------------------------------------------------------------
        // 2. Single SOQL query for the whole batch.
        //    SOQL string comparison is case-insensitive, so Contacts stored with
        //    different casing still match. The in-memory key below is also
        //    normalised, so the Apex-side comparison stays case-insensitive.
        //    ORDER BY puts the earliest CreatedDate first (Id keeps it stable).
        // ------------------------------------------------------------------
        Map<String, Contact> earliestByNormalizedEmail = new Map<String, Contact>();

        if (!emailsToFind.isEmpty()) {
            List<Contact> matches = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailsToFind
                ORDER BY CreatedDate ASC, Id ASC
            ];

            for (Contact con : matches) {
                String key = normalize(con.Email);
                // First record for a given normalised email wins => earliest CreatedDate.
                if (String.isNotBlank(key) && !earliestByNormalizedEmail.containsKey(key)) {
                    earliestByNormalizedEmail.put(key, con);
                }
            }
        }

        // ------------------------------------------------------------------
        // 3. Build exactly one Result per Request, in request order.
        // ------------------------------------------------------------------
        for (Integer i = 0; i < requests.size(); i++) {
            Result res = new Result();
            res.found = false;
            res.contactId = null;

            String key = normalizedInputs[i];
            if (String.isNotBlank(key)) {
                Contact con = earliestByNormalizedEmail.get(key);
                if (con != null) {
                    res.found = true;
                    res.contactId = con.Id;
                }
            }

            results.add(res);
        }

        return results;
    }

    /**
     * Null/blank-safe normalisation: trims surrounding whitespace and lower-cases,
     * so comparisons are case-insensitive on both the input and stored values.
     */
    private static String normalize(String value) {
        if (value == null) {
            return '';
        }
        return value.trim().toLowerCase();
    }

    public class Request {
        @InvocableVariable(
            label='Email'
            description='Email address of the Contact to find.'
            required=true
        )
        public String email;
    }

    public class Result {
        @InvocableVariable(
            label='Contact ID'
            description='ID of the matching Contact, or null when no Contact was found.'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True when a matching Contact was found.'
        )
        public Boolean found;
    }
}
