/**
 * Parser for the JSON order documents posted to the e-commerce REST endpoint,
 * plus the acknowledgement document returned to the caller.
 *
 * Contract notes
 *  - Only PayloadException ever leaves this class: any unexpected failure is
 *    translated before it can escape.
 *  - Unknown JSON properties (at any depth) are ignored - the parser reads
 *    exactly the keys it knows about and nothing else.
 *  - Money maths uses Apex Decimal (exact base-10 arithmetic). Every line total
 *    is rounded to two decimals with ties rounded half up (1.005 -> 1.01) and
 *    the order total is the sum of those already rounded line totals.
 *  - `lines` missing/null yields an empty list (a non-array `values` value is
 *    likewise treated as "no lines"); a missing `customer` yields a null
 *    customerEmail; a missing or null `discount` yields 0.
 */
public with sharing class OrderPayloadParser {

    /** The single exception type raised while parsing or acknowledging. */
    public class PayloadException extends Exception {
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    /* ------------------------------------------------------------------ */
    /* Public API                                                          */
    /* ------------------------------------------------------------------ */

    /**
     * Parses a raw JSON body into an Order.
     *
     * @param body the raw request body; may be null.
     * @return a fully populated Order (lines never null, total never null).
     * @throws PayloadException when the body is null/blank, is not valid JSON,
     *         is not a JSON object, has a missing/blank `number`, or contains a
     *         line without a sku, without a positive quantity, or without a
     *         non-negative unitPrice. No other exception type is ever thrown.
     */
    public static Order parse(String body) {
        try {
            return readOrder(body);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            // Defensive: guarantee callers only ever see PayloadException.
            throw new PayloadException('Unable to parse the order payload: ' + e.getMessage());
        }
    }

    /**
     * Renders the acknowledgement document: a JSON object with exactly the
     * keys `number`, `status`, `lineCount` and `total` (the last two as JSON
     * numbers).
     *
     * @param order the parsed order (tolerated as null for robustness).
     * @return the serialised acknowledgement JSON.
     */
    public static String toAcknowledgement(Order order) {
        String orderNumber;
        Integer lineCount = 0;
        Decimal total = 0;

        if (order != null) {
            orderNumber = order.orderNumber;
            if (order.lines != null) {
                lineCount = order.lines.size();
            }
            if (order.total != null) {
                total = order.total;
            }
        }

        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', lineCount);
        ack.put('total', total);

        return JSON.serialize(ack);
    }

    /* ------------------------------------------------------------------ */
    /* Reading                                                             */
    /* ------------------------------------------------------------------ */

    private static Order readOrder(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('The request body must not be empty.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('The request body is not valid JSON: ' + e.getMessage());
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('The request body must be a JSON object.');
        }

        Map<String, Object> json = (Map<String, Object>) root;

        Order order = new Order();
        order.orderNumber = requireText(json.get('number'), 'number');
        order.orderDate = readDate(json.get('date'));
        order.currencyCode = readText(json.get('currency'));
        order.customerEmail = readCustomerEmail(json.get('customer'));
        order.lines = readLines(json.get('lines'));
        order.total = sumLineTotals(order.lines);
        return order;
    }

    private static String readCustomerEmail(Object raw) {
        if (!(raw instanceof Map<String, Object>)) {
            return null; // `customer` may be missing entirely.
        }
        Map<String, Object> customer = (Map<String, Object>) raw;
        return readText(customer.get('email'));
    }

    private static List<Line> readLines(Object raw) {
        List<Line> lines = new List<Line>();
        if (raw == null) {
            return lines; // missing or null `lines` -> empty list
        }
        if (!(raw instanceof List<Object>)) {
            return lines; // unusable value -> treated as "no lines", never throws
        }
        List<Object> items = (List<Object>) raw;
        for (Object item : items) {
            lines.add(readLine(item));
        }
        return lines;
    }

    private static Line readLine(Object item) {
        if (!(item instanceof Map<String, Object>)) {
            throw new PayloadException(
                'Every entry of "lines" must be a JSON object carrying a "sku".'
            );
        }
        Map<String, Object> json = (Map<String, Object>) item;

        Line line = new Line();
        line.sku = requireText(json.get('sku'), 'sku');

        // ---- quantity: required and must be positive -------------------
        Decimal quantityValue = readDecimal(json.get('quantity'));
        if (quantityValue == null || quantityValue <= 0) {
            throw new PayloadException(
                'Line "' + line.sku + '" requires a positive "quantity".'
            );
        }
        Integer quantity = quantityValue.intValue();
        if (quantity == null || quantity <= 0) {
            throw new PayloadException(
                'Line "' + line.sku + '" requires a positive "quantity".'
            );
        }
        line.quantity = quantity;

        // ---- unitPrice: required and must not be negative --------------
        Decimal unitPrice = readDecimal(json.get('unitPrice'));
        if (unitPrice == null || unitPrice < 0) {
            throw new PayloadException(
                'Line "' + line.sku + '" requires a non-negative "unitPrice".'
            );
        }
        line.unitPrice = unitPrice;

        // ---- discount: fraction in [0..1], missing/null means 0 ---------
        line.discount = readDiscount(json.get('discount'));

        // ---- money ------------------------------------------------------
        Decimal factor = 1 - line.discount;
        Decimal rawTotal = line.quantity * line.unitPrice * factor;
        line.lineTotal = rawTotal.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static Decimal sumLineTotals(List<Line> lines) {
        Decimal total = 0;
        if (lines == null) {
            return total;
        }
        for (Line line : lines) {
            if (line.lineTotal != null) {
                total += line.lineTotal;
            }
        }
        return total;
    }

    /* ------------------------------------------------------------------ */
    /* Small value readers                                                 */
    /* ------------------------------------------------------------------ */

    /** Reads a scalar as text (strings verbatim, numbers stringified). */
    private static String readText(Object raw) {
        if (raw instanceof String) {
            return (String) raw;
        }
        if (isNumeric(raw)) {
            return String.valueOf(raw);
        }
        return null;
    }

    /** Like readText but rejects null/blank values with a PayloadException. */
    private static String requireText(Object raw, String fieldName) {
        String value = readText(raw);
        if (String.isBlank(value)) {
            throw new PayloadException(
                'The "' + fieldName + '" field is required and must not be blank.'
            );
        }
        return value;
    }

    /** Reads an ISO yyyy-MM-dd date; anything unusable yields null. */
    private static Date readDate(Object raw) {
        if (!(raw instanceof String)) {
            return null;
        }
        String value = ((String) raw).trim();
        if (String.isBlank(value)) {
            return null;
        }
        try {
            return Date.valueOf(value);
        } catch (Exception e) {
            return null; // malformed date is not a listed failure condition
        }
    }

    /** Reads a discount fraction; missing, null or out of [0..1] means 0. */
    private static Decimal readDiscount(Object raw) {
        Decimal value = readDecimal(raw);
        if (value == null || value < 0 || value > 1) {
            return 0;
        }
        return value;
    }

    /** Reads a JSON number of any numeric runtime type, else null. */
    private static Decimal readDecimal(Object raw) {
        if (raw instanceof Decimal) {
            return (Decimal) raw;
        }
        if (raw instanceof Integer || raw instanceof Long || raw instanceof Double) {
            return Decimal.valueOf(String.valueOf(raw));
        }
        return null;
    }

    private static Boolean isNumeric(Object raw) {
        return raw instanceof Decimal
            || raw instanceof Integer
            || raw instanceof Long
            || raw instanceof Double;
    }
}
