        assertQuote(5.00, 0.5, 'DOMESTIC', false, BELOW_FREE_THRESHOLD);
        assertQuote(5.00, 1, 'DOMESTIC', false, BELOW_FREE_THRESHOLD);      // inclusive upper bound
        assertQuote(5.00, 1.0001, 'DOMESTIC', false, BELOW_FREE_THRESHOLD); // just outside -> next band
    }

    @IsTest
