        assertQuote(18.00, 12, 'DOMESTIC', false, BELOW_FREE_THRESHOLD);
        assertQuote(18.00, 19.99, 'DOMESTIC', false, BELOW_FREE_THRESHOLD);
        assertQuote(18.00, 20, 'DOMESTIC', false, BELOW_FREE_THRESHOLD);   // inclusive upper bound
