public with sharing class LeadImportService {

    /**
     * Imports a list of leads, inserting every lead that can be inserted even when
     * other leads in the same call fail, and reporting per-row errors by input index.
     *
     * @param leads the leads to import (may be null or empty)
     * @return an ImportResult whose members are never null
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Pass 1: normalize, flag duplicate emails, and decide which rows go to the database.
        Set<String> seenEmails = new Set<String>();
        List<Lead> toInsert = new List<Lead>();
        List<Integer> toInsertIndexes = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            if (lead == null) {
                result.errorsByIndex.put(i, 'Lead is null.');
                continue;
            }

            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            String emailKey = String.isBlank(lead.Email)
                ? null
                : lead.Email.trim().toLowerCase();

            if (emailKey != null) {
                if (seenEmails.contains(emailKey)) {
                    // Never sent to the database, regardless of whether the first one succeeded.
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + emailKey);
                    continue;
                }
                seenEmails.add(emailKey);
            }

            toInsert.add(lead);
            toInsertIndexes.add(i);
        }

        // Pass 2: a single DML statement for the whole call.
        if (toInsert.isEmpty()) {
            return result;
        }

        List<Database.SaveResult> saveResults = Database.insert(toInsert, false);

        // Results are in the same order as the input list passed to the DML call.
        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult sr = saveResults[j];
            Integer originalIndex = toInsertIndexes[j];

            if (sr.isSuccess()) {
                result.insertedIds.add(sr.getId());
                result.successCount++;
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(originalIndex, String.join(messages, '; '));
            }
        }

        return result;
    }

    /**
     * Outcome of a single import call.
     */
    public class ImportResult {
        public Integer successCount = 0;
        public List<Id> insertedIds = new List<Id>();
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>();
    }
}
