/**
 * AccountScoringJob
 *
 * Re-rates up to 50,000 Accounts on demand (Marketing button) by chaining queueable
 * executions, 200 Accounts at a time.
 *
 *     Id jobId = AccountScoringJob.start(accountIds);   // null when there is nothing to do
 *
 * Each execution spends exactly one SOQL query and one DML statement:
 *   1. queries the first 200 pending Account Ids,
 *   2. sets Rating from AnnualRevenue
 *      (>= 1,000,000 -> Hot, >= 100,000 -> Warm, otherwise Cold, including null),
 *   3. updates those Accounts (one DML statement, whether or not rows changed),
 *   4. enqueues the next AccountScoringJob with the Ids that are still pending.
 *
 * Chaining is never short-circuited for tests, so a single
 * Test.startTest()/Test.stopTest() window walks the whole chain to completion, no
 * matter how many Ids were submitted.
 *
 * Declared `without sharing` on purpose: the job receives an explicit list of Account
 * Ids and must rate every one of them, so row-level sharing must never silently drop
 * records from the chunk query. Sharing does not restrict DML, the class returns no
 * data, and the rating itself is not sensitive - no data is exposed by running in
 * system mode.
 */
public without sharing class AccountScoringJob implements Queueable {

    /** Accounts handled per execution: keeps every execution at one query + one DML. */
    private static final Integer CHUNK_SIZE = 200;

    /** Rating thresholds taken from AnnualRevenue. */
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    /** Ids still to be rated: this execution's chunk plus everything chained after it. */
    private final List<Id> pendingIds;

    /**
     * @param accountIds Accounts to (re)rate. A null or empty list is accepted and
     *                   results in no work and no chained job.
     */
    public AccountScoringJob(List<Id> accountIds) {
        // Defensive copy: later mutation of the caller's list must not corrupt the chain.
        this.pendingIds = accountIds == null ? new List<Id>() : new List<Id>(accountIds);
    }

    /**
     * Rates the first 200 pending Accounts and chains the rest.
     *
     * @param context Unused; may be null when execute() is invoked directly.
     */
    public void execute(QueueableContext context) {
        List<Id> ids = this.pendingIds == null ? new List<Id>() : this.pendingIds;

        // Split the pending Ids: this execution's chunk and everything after it.
        Integer chunkEnd = ids.size() < CHUNK_SIZE ? ids.size() : CHUNK_SIZE;
        List<Id> chunkIds = ids.subList(0, chunkEnd);
        List<Id> remainingIds = ids.subList(chunkEnd, ids.size());

        // One SOQL query per execution (a bind on an empty list simply returns no rows).
        List<Account> accounts = [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :chunkIds
        ];

        for (Account account : accounts) {
            account.Rating = ratingFor(account.AnnualRevenue);
        }

        // One DML statement per execution.
        update accounts;

        // Chain: hand everything still pending to the next job.
        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    /**
     * @param annualRevenue Account AnnualRevenue; null (blank) is treated as Cold.
     * @return Hot at/above 1,000,000, Warm at/above 100,000, otherwise Cold.
     */
    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue != null) {
            if (annualRevenue >= HOT_THRESHOLD) {
                return RATING_HOT;
            }
            if (annualRevenue >= WARM_THRESHOLD) {
                return RATING_WARM;
            }
        }
        return RATING_COLD;
    }

    /**
     * Starts the chain.
     *
     * @param accountIds Accounts to (re)rate.
     * @return the Id of the first enqueued job, or null when nothing was enqueued.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
