/**
 * Queueable that marks a set of Accounts as synced to the ERP.
 *
 * A Finalizer is attached before any work is done, so every run - successful or
 * failed - writes exactly one FB_Job_Log__c row and failed runs are retried
 * (see ErpSyncFinalizer).
 */
public with sharing class ErpAccountSyncJob implements Queueable {

    /** Value written to Account.Description when the sync succeeds. */
    private static final String SYNCED_DESCRIPTION = 'Synced to ERP';

    /** Accounts to sync - kept as state so the finalizer/retries use the same set. */
    private final Set<Id> accountIds;

    /** 1-based attempt counter; the first run is attempt 1. */
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        // Defensive copies / sane defaults so the job state is always serializable
        // and the retry chain never starts below attempt 1.
        this.accountIds = (accountIds == null) ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt    = (attempt == null)    ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // FIRST thing that happens: register the transaction finalizer so that a
        // log row (and, on failure, a retry) is produced no matter how this run ends.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        if (accountIds.isEmpty()) {
            return;
        }

        // Bulk-safe: one DML statement for the whole set, only Id + Description set,
        // so no other field values are overwritten.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountsToUpdate.add(new Account(Id = accountId, Description = SYNCED_DESCRIPTION));
            }
        }

        if (accountsToUpdate.isEmpty()) {
            return;
        }

        // All-or-nothing and deliberately NOT caught: if any account cannot be
        // saved the exception propagates, the whole transaction (all of these
        // changes) is rolled back, the job ends in an error state and the
        // finalizer records the failure and schedules the next attempt.
        update accountsToUpdate;
    }
}
