/**
 * Schedulable job that purges old FB_Integration_Log__c records.
 *
 * Retention rules:
 *   - Non-ERROR logs (including logs with a blank Level__c) are deleted
 *     once they are older than 30 days.
 *   - ERROR logs are kept for 180 days before being deleted.
 */
public with sharing class LogPurgeJob implements Schedulable {
    /** Retention thresholds in days. */
    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Nightly schedule: every day at 02:00. */
    private static final String NIGHTLY_CRON_EXPRESSION = '0 0 2 * * ?';

    /** Job name used when scheduling. */
    private static final String JOB_NAME = 'Log purge (nightly)';

    /** Batch size used for the delete DML statements (safe under governor limits). */
    private static final Integer DELETE_BATCH_SIZE = 200;

    /** No-argument constructor required for schedulable/serializable classes. */
    public LogPurgeJob() {
    }

    /**
     * Executes the purge when the job runs.
     *
     * @param sc The Schedulable context provided by the platform.
     */
    public void execute(SchedulableContext sc) {
        Datetime now = Datetime.now();

        Datetime standardCutoff = now.addDays(-STANDARD_RETENTION_DAYS);
        Datetime errorCutoff = now.addDays(-ERROR_RETENTION_DAYS);

        // Level__c is a nullable Text field: a null (blank) Level is NOT equal
        // to 'ERROR' in SOQL, so null must be matched explicitly with OR.
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :standardCutoff
              AND (
                    Level__c = null
                 OR Level__c != 'ERROR'
                 OR CreatedDate < :errorCutoff
              )
            ORDER BY CreatedDate
        ];

        if (logsToDelete.isEmpty()) {
            return;
        }

        // Delete in batches so we never exceed the DML row limit (10,000 rows)
        // in a single statement. allOrNone = false keeps a single bad record
        // from aborting the whole purge.
        for (Integer startIndex = 0;
             startIndex < logsToDelete.size();
             startIndex += DELETE_BATCH_SIZE) {

            Integer endIndex = Math.min(
                startIndex + DELETE_BATCH_SIZE,
                logsToDelete.size()
            );

            Database.delete(
                new List<FB_Integration_Log__c>(
                    logsToDelete.subList(startIndex, endIndex)
                ),
                false
            );
        }
    }

    /**
     * Schedules the purge job to run nightly at 02:00.
     *
     * @return The Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        return System.schedule(
            JOB_NAME,
            NIGHTLY_CRON_EXPRESSION,
            new LogPurgeJob()
        );
    }
}
