public class Application
{
	/**
	 * UnitOfWork factory.
	 *
	 * All four SObject types used by the team are registered so that a single
	 * commitWork() can insert Accounts, Contacts, Opportunities and
	 * OpportunityContactRoles - including every parent/child reference between them.
	 *
	 * The order of the list is significant:
	 *   - fflib_SObjectUnitOfWork inserts in list order and deletes in reverse order,
	 *     so Accounts are inserted before the Contacts/Opportunities that point at them
	 *     (Contact.AccountId, Opportunity.AccountId) and OpportunityContactRoles are
	 *     inserted last, after the Opportunities and Contacts they reference.
	 *
	 * The references themselves (Contact.AccountId -> new Account,
	 * Opportunity.AccountId -> new Account, OpportunityContactRole.OpportunityId ->
	 * new Opportunity, OpportunityContactRole.ContactId -> new Contact) are all
	 * registered through the unit of work with
	 * registerNew(record, relatedToField, relatedTo) / registerRelationship(...),
	 * and fflib resolves them to the generated ids during commitWork().
	 */
	public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
		new fflib_Application.UnitOfWorkFactory(
			new List<Schema.SObjectType>
			{
				Account.SObjectType,
				Contact.SObjectType,
				Opportunity.SObjectType,
				OpportunityContactRole.SObjectType
			}
		);

	/**
	 * Service factory.
	 *
	 * Application.Service.newInstance(IAccountsService.class) returns an
	 * AccountsServiceImpl. Tests can replace the mapping with
	 * Application.Service.setMock(IAccountsService.class, MyServiceMock.class).
	 */
	public static final fflib_Application.ServiceFactory Service =
		new fflib_Application.ServiceFactory(
			new Map<Type, Type>
			{
				IAccountsService.class => AccountsServiceImpl.class
			}
		);

	/**
	 * Selector factory.
	 *
	 * Maps each SObject type to the selector that reads it, so callers (and the
	 * domain factory below) can do
	 * ((AccountsSelector) Application.Selector.newInstance(Account.SObjectType)).selectById(ids)
	 * without hard-wiring the implementation class. Tests can replace a mapping with
	 * Application.Selector.setMock(Account.SObjectType, MyAccountsSelectorMock.class).
	 */
	public static final fflib_Application.SelectorFactory Selector =
		new fflib_Application.SelectorFactory(
			new Map<Schema.SObjectType, Type>
			{
				Account.SObjectType => AccountsSelector.class,
				Contact.SObjectType => ContactsSelector.class
			}
		);

	/**
	 * Domain factory.
	 *
	 * Built on the Selector factory above (declared after it so the static
	 * initializer has already run), therefore
	 * Application.Domain.newInstance(Set<Id> accountIds) queries the Accounts through
	 * Application.Selector (i.e. AccountsSelector.selectById) and then wraps the
	 * returned records in the Accounts domain via its Constructor.
	 * Tests can replace the mapping with
	 * Application.Domain.setMock(Account.SObjectType, MyAccountsDomainMock.class).
	 */
	public static final fflib_Application.DomainFactory Domain =
		new fflib_Application.DomainFactory(
			Selector,
			new Map<Schema.SObjectType, Type>
			{
				Account.SObjectType => Accounts.Constructor.class
			}
		);
}
