public with sharing class ContactsSelector extends fflib_SObjectSelector
{
	/**
	 * Default constructor.
	 *
	 * Deliberately uses the fflib defaults (selector field list included in the
	 * query, no FLS enforcement, default ordering) so the selector behaves
	 * consistently with the rest of the Apex Enterprise Patterns library.
	 */
	public ContactsSelector()
	{
		super();
	}

	/**
	 * The list of fields this selector is allowed to query.
	 */
	public List<Schema.SObjectField> getSObjectFieldList()
	{
		return new List<Schema.SObjectField>
		{
			Contact.Id,
			Contact.FirstName,
			Contact.LastName,
			Contact.Email,
			Contact.Title,
			Contact.AccountId
		};
	}

	/**
	 * The SObject type handled by this selector.
	 */
	public Schema.SObjectType getSObjectType()
	{
		return Contact.SObjectType;
	}

	/**
	 * Returns the contacts with the given ids, with every field of the
	 * selector's field list populated, in a single query.
	 *
	 * @param contactIds The Set of Contact Ids to search for
	 *
	 * @return List of matching Contacts; an empty list when the input set is
	 *         null or empty (no query is executed in that case).
	 */
	public List<Contact> selectById(Set<Id> contactIds)
	{
		if (contactIds == null || contactIds.isEmpty())
		{
			return new List<Contact>();
		}

		String soql = newQueryFactory()
			.setCondition('Id IN :contactIds')
			.toSOQL();

		return (List<Contact>) Database.query(soql);
	}
