```apex
public with sharing class CaseEscalationService
{
	public class EscalationException extends Exception {}

	public static void escalate(Set<Id> caseIds, String reason)
	{
		// Validate the reason before touching anything else.
		if (String.isBlank(reason))
		{
			throw new EscalationException('An escalation reason is required.');
		}

		// Nothing to do.
		if (caseIds == null || caseIds.isEmpty())
		{
			return;
		}

		List<Case> casesToEscalate = new List<Case>();
		for (Case aCase : CasesSelector.newInstance().selectById(caseIds))
		{
			// Skip closed cases and cases that are already escalated.
			if (aCase.Status == 'Closed' || aCase.IsEscalated)
			{
				continue;
			}

			casesToEscalate.add(aCase);
		}

		// No case needs escalating: do not open a unit of work / do not commit.
		if (casesToEscalate.isEmpty())
		{
			return;
		}

		fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

		Date tomorrow = Date.today().addDays(1);

		for (Case aCase : casesToEscalate)
		{
			aCase.IsEscalated = true;
			aCase.Priority = 'High';
			uow.registerDirty(aCase);

			uow.registerNew(
				new Task(
					Subject = 'Escalated: ' + reason,
					WhatId = aCase.Id,
					OwnerId = aCase.OwnerId,
					ActivityDate = tomorrow,
					Priority = 'High'
				)
			);
		}

		uow.commitWork();
	}
}
