/**
 * Service responsible for creating Accounts together with their initial
 * Contacts, persisting everything through a single fflib Unit of Work.
 *
 * Uses the Apex Enterprise Patterns (fflib-apex-common) Unit of Work so that
 * all DML for the transaction is performed in a single, ordered, bulk-safe
 * operation.
 */
public with sharing class AccountOnboardingService
{
	/**
	 * Creates one Account per map key and, for each last name in the key's
	 * list, one Contact related to that Account.
	 *
	 * @param contactLastNamesByAccountName Map of Account name -> list of Contact last names.
	 * @return The newly created Accounts, with their Ids populated.
	 */
	public static List<Account> createAccountsWithContacts(
		Map<String, List<String>> contactLastNamesByAccountName)
	{
		List<Account> newAccounts = new List<Account>();

		// Null/empty input: nothing to do, no DML, no Unit of Work work.
		if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty())
		{
			return newAccounts;
		}

		// A single Unit of Work covering both objects touched in this operation.
		fflib_SObjectUnitOfWork unitOfWork = new fflib_SObjectUnitOfWork(
			new List<SObjectType>
			{
				Account.SObjectType,
				Contact.SObjectType
			}
		);

		for (String accountName : contactLastNamesByAccountName.keySet())
		{
			List<String> lastNames = contactLastNamesByAccountName.get(accountName);

			// Defensive: treat a null value as "no contacts for this account".
			if (String.isBlank(accountName) || lastNames == null || lastNames.isEmpty())
			{
				continue;
			}

			Account account = new Account(Name = accountName);
			unitOfWork.registerNew(account);
			newAccounts.add(account);

			for (String lastName : lastNames)
			{
				if (String.isBlank(lastName))
				{
					continue;
				}

				Contact contact = new Contact(LastName = lastName);
				// Wire the foreign key before insert; the UoW rewires it to the
				// generated Account Id when it performs the insert.
				unitOfWork.registerRelationship(contact, Contact.AccountId, account);
				unitOfWork.registerNew(contact);
			}
		}

		// Single, ordered DML for the whole transaction (Accounts before Contacts).
		unitOfWork.commitWork();

		return newAccounts;
	}
}
