public with sharing class PipelineSummary {

    // The four open stages sales ops manages. Fixed, hardcoded list:
    // four queries max, no data-dependent query growth.
    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Sums Opportunity.Amount per stage for opportunities whose CloseDate
     * falls between fromDate and toDate (both inclusive).
     *
     * Always returns exactly the four stage keys; stages with no matching
     * opportunities map to 0 (never null). Null Amounts contribute nothing.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        // One aggregate query per stage. The loop runs exactly four times, so
        // this is a constant four queries regardless of row volume, and the
        // per-query filter stays simple and readable.
        for (String stage : STAGES) {
            Decimal stageTotal = 0;

            List<AggregateResult> results = [
                SELECT SUM(Amount) sum
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            // SUM over zero rows can yield a null aggregate value depending
            // on the shape of the result, so normalize to 0.
            if (!results.isEmpty() && results[0].get('sum') != null) {
                stageTotal = (Decimal) results[0].get('sum');
            }

            totals.put(stage, stageTotal);
        }

        return totals;
    }
}
