File: force-app/main/default/classes/ErpCustomerSync.cls
```apex
/**
 * Creates customers in the ERP for newly inserted Accounts.
 *
 * Contract (ERP):
 *   POST callout:ERP/api/customers
 *   Content-Type: application/json
 *   [{"salesforceId": "001...", "name": "Acme GmbH", "country": "Germany"}]
 *   -> 202 Accepted
 *
 * Exactly one request is sent per account (an array with a single element), so the ERP
 * team can trace every account on its own. `country` is null when BillingCountry is blank.
 *
 * Execution model:
 *   - AccountTrigger (after insert) enqueues one Queueable per trigger run.
 *   - The job sends one request per account, stopping at the platform callout limit
 *     (100 per transaction) and chaining itself for the remaining accounts. A batch of
 *     200 accounts therefore uses 2 jobs, never 200 and never >100 callouts in one job.
 *   - Only one job is enqueued per transaction, so no per-transaction @future (50) or
 *     enqueue limits can be hit.
 *
 * Error handling and retries are out of scope for this change.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final String ENDPOINT     = 'callout:ERP/api/customers';
    private static final String CONTENT_TYPE = 'application/json';

    /** Customers that still have to be pushed, in trigger order. */
    private final List<Customer> customers;

    /** Index of the next customer to push. */
    private Integer nextIndex;

    public ErpCustomerSync(List<Customer> customers, Integer nextIndex) {
        this.customers = (customers == null) ? new List<Customer>() : customers;
        this.nextIndex  = (nextIndex == null) ? 0 : nextIndex;
    }

    /**
     * Entry point called from AccountTrigger (after insert).
     * Builds the ERP payloads from the records seen at creation time and queues the job.
     */
    public static void syncNewAccounts(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<Customer> customers = new List<Customer>();
        for (Account account : newAccounts) {
            customers.add(toCustomer(account));
        }

        // One async job per trigger run; it performs one HTTP request per account.
        System.enqueueJob(new ErpCustomerSync(customers, 0));
    }

    /**
     * Sends one request per remaining customer until the callout budget of this
     * transaction is used up, then chains another job for the rest.
     */
    public void execute(QueueableContext context) {
        Integer calloutLimit = Limits.getLimitCallouts();

        while (nextIndex < customers.size() && Limits.getCallouts() < calloutLimit) {
            sendOneRequest(customers[nextIndex]);
            nextIndex++;
        }

        if (nextIndex < customers.size()) {
            // Still customers left -> chain instead of exceeding the callout limit.
            System.enqueueJob(new ErpCustomerSync(customers, nextIndex));
        }
    }

    /** Exactly one HTTP request for this customer (body: array with a single element). */
    private static void sendOneRequest(Customer customer) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', CONTENT_TYPE);
        request.setBody(JSON.serialize(new List<Customer>{ customer }));

        // ERP answers 202 Accepted; response/error handling and retries are out of scope.
        new Http().send(request);
    }

    /** Maps an Account to the ERP payload; BillingCountry blank -> country null. */
    private static Customer toCustomer(Account account) {
        return new Customer(
            String.valueOf(account.Id),   // String.valueOf(Id) yields the 18-character Id
            account.Name,
            String.isBlank(account.BillingCountry) ? null : account.BillingCountry
        );
    }

    /**
     * DTO that mirrors the ERP contract field-for-field, so JSON.serialize produces the
     * required keys (salesforceId, name, country) including explicit nulls.
     */
    public class Customer {
        public String salesforceId;
        public String name;
        public String country;

        public Customer(String salesforceId, String name, String country) {
            this.salesforceId = salesforceId;
            this.name = name;
            this.country = country;
        }
    }
}
```

