/**
 * Keeps Account.Rating in sync with the account's open pipeline.
 *
 * Fires once per opportunity that could change the parent account's rating:
 *  - on insert (a new opportunity may create, keep or remove open pipeline), and
 *  - on update when StageName or Amount changed (the only fields that can move the
 *    account between Cold / Warm / Hot).
 *
 * The recalculation is handed to AccountRatingService.recalculate(), an @future method,
 * so the opportunity DML transaction stays fast and the aggregate SOQL + account DML
 * happen asynchronously in their own transaction.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    // after-context only: we never write to the opportunity itself, we only ask for an
    // asynchronous recalculation of the parent account.
    for (Opportunity opp : Trigger.new) {

        // A new/updated opportunity with no account has nothing to recalculate.
        if (opp.AccountId == null) {
            continue;
        }

        if (Trigger.isUpdate) {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
            // Only StageName and Amount can change whether this opportunity counts as
            // open pipeline or crosses the 100k threshold - skip the useless future call.
            if (oldOpp.StageName == opp.StageName && oldOpp.Amount == opp.Amount) {
                continue;
            }
        }

        // Deliberately one call per opportunity: simple, order-independent and
        // comfortably inside the 500 @future calls per transaction limit (CPQ sends
        // batches of at most 200 opportunities per transaction).
        AccountRatingService.recalculate(opp.AccountId);
    }
}
```

