import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

// Fields we need from the record page LDS cache.
const ACCOUNT_FIELDS = [
    NAME_FIELD,
    INDUSTRY_FIELD,
    ANNUAL_REVENUE_FIELD,
    OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    /**
     * Provided by the record page. Reactive: when the console tab is reused
     * and recordId changes, getRecord re-executes automatically.
     */
    @api recordId;

    record;
    error;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: ACCOUNT_FIELDS
    })
    wiredAccount({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        }
    }

    // ---- Loading state -------------------------------------------------
    get isLoading() {
        return !this.record && !this.error;
    }

    // ---- Error state ----------------------------------------------------
    get errorMessage() {
        return this.error && this.error.body ? this.error.body.message : null;
    }

    get hasError() {
        return !!this.errorMessage;
    }

    // ---- Field helpers --------------------------------------------------
    get name() {
        return this.#fieldValue(NAME_FIELD);
    }

    get industry() {
        return this.#fieldValue(INDUSTRY_FIELD);
    }

    get hasIndustry() {
        const value = this.industry;
        return value !== undefined && value !== null && value !== '';
    }

    get annualRevenue() {
        return this.#fieldValue(ANNUAL_REVENUE_FIELD);
    }

    get hasRevenue() {
        const value = this.annualRevenue;
        return value !== undefined && value !== null && value !== '';
    }

    get ownerName() {
        return this.#fieldValue(OWNER_NAME_FIELD);
    }

    /**
     * Reads a field value off the wired record, tolerating missing
     * (optional) fields without throwing.
     */
    #fieldValue(fieldApiName) {
        if (!this.record || !this.record.fields) {
            return undefined;
        }
        const field = this.record.fields[fieldApiName];
        return field && field.value !== undefined ? field.value : undefined;
    }
}
