import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    /**
     * The Id of the Account record page hosting this component.
     */
    @api recordId;

    /**
     * Resolved URL for the "My_Open_Cases" Case list view.
     * Empty until NavigationMixin.GenerateUrl resolves.
     */
    caseListUrl;

    /**
     * Build the Case list view URL as soon as the component is inserted.
     */
    connectedCallback() {
        const caseListPageReference = {
            type: 'standard__objectPage',
            attributes: {
                apiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        };

        this[NavigationMixin.GenerateUrl](caseListPageReference)
            .then((url) => {
                this.caseListUrl = url;
            })
            .catch((error) => {
                // Never fall back to hand-built URLs; surface the failure instead.
                // eslint-disable-next-line no-console
                console.error('Unable to generate the Case list view URL', error);
            });
    }

    /**
     * Single click handler for all quick-link buttons.
     * Navigation is always delegated to the Lightning navigation service.
     */
    handleAction(event) {
        const action = event.currentTarget.dataset.action;
        let pageReference;

        switch (action) {
            case 'new-contact':
                if (!this.recordId) {
                    return;
                }
                pageReference = {
                    type: 'standard__objectPage',
                    attributes: {
                        apiName: 'Contact',
                        actionName: 'new'
                    },
                    state: {
                        defaultFieldValues: encodeDefaultFieldValues({
                            AccountId: this.recordId
                        })
                    }
                };
                break;

            case 'contacts':
                if (!this.recordId) {
                    return;
                }
                pageReference = {
                    type: 'standard__recordRelationshipPage',
                    attributes: {
                        recordId: this.recordId,
                        relationshipApiName: 'Contacts',
                        actionName: 'view'
                    }
                };
                break;

            case 'edit':
                if (!this.recordId) {
                    return;
                }
                pageReference = {
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        actionName: 'edit'
                    }
                };
                break;

            default:
                return;
        }

        this[NavigationMixin.Navigate](pageReference);
    }
}
