/**
 * Reusable WAI-ARIA disclosure ("collapsible section") component.
 *
 * Usage:
 *   <c-collapsible-section>
 *       <span slot="title">Billing details</span>
 *       <p>Any body content…</p>
 *   </c-collapsible-section>
 *
 * Behaviour:
 *   - Starts collapsed.
 *   - The `title` slot renders inside a native <button class="section-toggle">.
 *   - The default slot renders inside a <div class="section-body"> that is always
 *     present in the DOM (so aria-controls always resolves) and is toggled with
 *     the native `hidden` attribute.
 *   - The button exposes aria-expanded ("true"/"false") and aria-controls.
 */
import { LightningElement } from 'lwc';

// Module-scoped counter used to build unique, stable element ids per instance.
let instanceCounter = 0;

const TOGGLE_PREFIX = 'section-toggle-';
const BODY_PREFIX = 'section-body-';

export default class CollapsibleSection extends LightningElement {
    // Internal disclosure state; the section starts collapsed.
    isExpanded = false;

    // Unique ids assigned once, when the component is inserted into the DOM.
    toggleId;
    bodyId;

    connectedCallback() {
        instanceCounter += 1;
        const suffix = `${instanceCounter}-${Math.random()
            .toString(36)
            .slice(2, 8)}`;

        this.toggleId = `${TOGGLE_PREFIX}${suffix}`;
        this.bodyId = `${BODY_PREFIX}${suffix}`;
    }

    /**
     * aria-expanded requires the literal strings "true" / "false".
     */
    get expandedValue() {
        return this.isExpanded ? 'true' : 'false';
    }

    /**
     * Drives the `hidden` attribute on the body div:
     * collapsed -> hidden, expanded -> attribute omitted.
     */
    get isCollapsed() {
        return !this.isExpanded;
    }

    /**
     * The body region is labelled by its toggle button.
     */
    get bodyLabelledBy() {
        return this.toggleId;
    }

    /**
     * Native <button> already provides Enter/Space activation and focus handling.
     */
    handleToggle() {
        this.isExpanded = !this.isExpanded;
    }
}
