import { api, track, LightningElement } from 'lwc';

export default class AccountContactList extends LightningElement {
    /**
     * Contacts passed in by the parent. The parent owns this array;
     * we only store a reference to it and re-render when a new one arrives.
     */
    @track _contacts = [];

    @api
    get contacts() {
        return this._contacts;
    }

    set contacts(value) {
        // Normalise undefined/null to an empty array so rendering logic is simple.
        this._contacts = Array.isArray(value) ? value : [];
    }

    /**
     * True when there is at least one contact to show.
     */
    get hasContacts() {
        return Array.isArray(this._contacts) && this._contacts.length > 0;
    }

    /**
     * Number of contacts.
     */
    get contactCount() {
        return this.hasContacts ? this._contacts.length : 0;
    }

    /**
     * "1 contact" when there is exactly one, "<n> contacts" otherwise.
     */
    get countLabel() {
        return this.contactCount === 1 ? '1 contact' : `${this.contactCount} contacts`;
    }

    /**
     * Contacts sorted by Name ascending for rendering.
     * Returns a new array; the parent-owned array is never mutated.
     */
    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        return [...this._contacts]
            .filter((contact) => contact != null)
            .sort((a, b) => {
                const nameA = a.Name != null ? String(a.Name) : '';
                const nameB = b.Name != null ? String(b.Name) : '';
                return nameA.localeCompare(nameB);
            });
    }
}
