/**
 * Type-ahead search over Contacts.
 *
 * - Debounces keystrokes (300 ms) and always searches with the latest trimmed value.
 * - Aborts (and clears) any pending work when fewer than 2 characters remain.
 * - Guards against out-of-order Apex responses: only the most recent request
 *   may write to the component state.
 * - Guards against responses (and pending debounce timers) after the component
 *   has been disconnected from the DOM.
 */
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_QUERY_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    /** Timer handle for the pending (not yet fired) debounced search. */
    _debounceTimer;

    /** Monotonic token identifying the most recently issued request. */
    _sequence = 0;

    /** Set to false in disconnectedCallback so pending work is never executed. */
    _isConnected = false;

    connectedCallback() {
        this._isConnected = true;
    }

    disconnectedCallback() {
        this._isConnected = false;
        // Never let a pending search run after the component has been removed.
        this._cancelPendingSearch();
        // Any in-flight response becomes stale the moment we disconnect.
        this._sequence += 1;
    }

    /**
     * Fired by lightning-input type="search" on every keystroke.
     * @param {InputEvent|Event} event - the input change event.
     */
    handleSearchChange(event) {
        const searchTerm = (event.target?.value ?? '').trim();

        // Always start from a clean slate: no timer may survive this keystroke.
        this._cancelPendingSearch();

        if (searchTerm.length < MIN_QUERY_LENGTH) {
            // Invalidate any in-flight request so its response is ignored.
            this._sequence += 1;
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = undefined;
            this._executeSearch(searchTerm);
        }, DEBOUNCE_MS);
    }

    _cancelPendingSearch() {
        if (this._debounceTimer !== undefined) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }
    }

    /**
     * Issues the imperative Apex call, tagged with a request token so that only
     * the response of the most recent request may update the rendered state.
     * @param {string} searchTerm - already trimmed search term.
     */
    _executeSearch(searchTerm) {
        // The component may have been removed while the search was pending.
        if (!this._isConnected) {
            return;
        }

        const requestId = ++this._sequence;

        searchContacts({ searchTerm })
            .then((result) => {
                // Ignore disconnected, superseded (out-of-order) responses.
                if (!this._isConnected || requestId !== this._sequence) {
                    return;
                }
                this.error = undefined;
                this.contacts = Array.isArray(result) ? result : [];
            })
            .catch((error) => {
                if (!this._isConnected || requestId !== this._sequence) {
                    return;
                }
                this.contacts = [];
                this.error = error;
            });
    }

    get hasResults() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }
}
