import { LightningElement, api, wire } from 'lwc';
import getContacts from '@salesforce/apex/ContactController.getContacts';
import { updateRecord, refreshApex } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    columns = COLUMNS;
    draftValues = [];

    // Keep the wired result so it can be passed to refreshApex
    wiredContacts;

    @wire(getContacts, { accountId: '$recordId' })
    wiredGetContacts(result) {
        this.wiredContacts = result;
    }

    get contacts() {
        return this.wiredContacts && this.wiredContacts.data
            ? this.wiredContacts.data
            : [];
    }

    handleSave(event) {
        const drafts = event.detail.draftValues;

        // One updateRecord call per draft row, in parallel;
        // each promise resolves to a result object so we wait for ALL of them.
        const updatePromises = drafts.map((draft) =>
            updateRecord({ fields: { ...draft } })
                .then(() => ({ success: true }))
                .catch((error) => ({ success: false, error }))
        );

        Promise.all(updatePromises)
            .then((results) => {
                const failure = results.find((result) => !result.success);

                if (failure) {
                    this.dispatchEvent(
                        new ShowToastEvent({
                            variant: 'error',
                            title: 'Could not save contacts',
                            message: failure.error.body.message
                        })
                    );
                    // Do not refresh or show the success toast on failure
                    return;
                }

                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Contacts updated'
                    })
                );
                this.draftValues = [];
                return refreshApex(this.wiredContacts);
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Could not save contacts',
                        message: error.body.message
                    })
                );
            });
    }
}
