    get pressedState() {
        return this._favorite ? 'true' : 'false';
    }

    // aria-label/title describe the action a click performs.
    get actionLabel() {
        return this._favorite ? Favorite_Remove : Favorite_Add;
    }

    handleClick() {
        const newFavorite = !this._favorite;

        // Optimistic UI update.
        this._favorite = newFavorite;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: newFavorite }
            })
        );
    }
