import { LightningElement, wire } from 'lwc';
import {
    MessageContext,
    APPLICATION_SCOPE,
    publish,
    subscribe,
    unsubscribe
} from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    // Id of the account currently shown in the record view form.
    selectedRecordId = null;

    // Keeps track of the active subscription so we never hold more than one.
    subscription = null;

    // The message context must be provided by a @wire before it can be used
    // with publish/subscribe/unsubscribe.
    @wire(MessageContext)
    messageContext;

    // The publisher lives in the utility bar, so we must subscribe with
    // APPLICATION_SCOPE. Re-subscribe every time (re)inserted, e.g. when a tab
    // is reopened.
    connectedCallback() {
        this.subscribeToMessageChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromMessageChannel();
    }

    subscribeToMessageChannel() {
        if (this.subscription) {
            return;
        }
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeFromMessageChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        // A message without a recordId (or a null recordId) clears the panel.
        const recordId = message && message.recordId ? message.recordId : null;
        this.selectedRecordId = recordId;
    }

    handleAction(event) {
        const action =
            event.target && event.target.dataset
                ? event.target.dataset.action
                : null;

        if (action === 'clear') {
            // Broadcast the clear so every listener (including this one)
            // resets its selection.
            publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, {
                recordId: null
            });
        }
    }
}
