import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /**
     * Public array of lines: [{ key, productName, quantity }].
     * @type {Array<{key: string, productName: string, quantity: number}>}
     */
    @api lines = [];

    /** True while the form-level error message should be rendered. */
    showError = false;

    /** Defensive copy of `lines` so the template never iterates a non-array. */
    get linesToRender() {
        return Array.isArray(this.lines) ? this.lines : [];
    }

    /** Every line editor currently rendered, in display order. */
    get lineEditors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    /** Single click handler; the button's data-action attribute selects the behaviour. */
    handleAction(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.resetAll();
        } else if (action === 'submit') {
            this.submitAll();
        }
    }

    /** Resets every line editor. */
    resetAll() {
        this.lineEditors.forEach((editor) => {
            editor.reset();
        });
    }

    /**
     * Validates every line editor, then either shows the form error or
     * dispatches `submit` with the collected values in display order.
     */
    submitAll() {
        const editors = this.lineEditors;

        // Always call validate() on every editor: no short-circuiting, so all
        // invalid lines show their errors at the same time.
        let valid = true;
        editors.forEach((editor) => {
            if (!editor.validate()) {
                valid = false;
            }
        });

        if (!valid) {
            this.showError = true;
            return;
        }

        const values = editors.map((editor) => editor.getValue());

        this.showError = false;
        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines: values }
            })
        );
    }
}
