import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

// Free / personal email domains that must not be accepted.
const FREE_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

// Whitelist of fields that may be updated from a change event.
const EDITABLE_FIELDS = ['fullName', 'email', 'company'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';
    isSubmitting = false;

    /**
     * Keeps the current value of the changed field (event.detail.value).
     */
    handleChange(event) {
        const field = event.target.dataset.field;
        if (field && EDITABLE_FIELDS.includes(field)) {
            this[field] = event.detail.value;
        }
    }

    /**
     * Single click handler; resolves the action from data-action.
     */
    handleClick(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'register') {
            this.handleRegister();
        }
    }

    /**
     * Validates every input (showing all messages at once) and, when valid,
     * calls the Apex method imperatively.
     */
    async handleRegister() {
        // ---- Step 1: work-email rule (runs before reportValidity) ----
        const emailInput = this.template.querySelector(
            'lightning-input[data-field="email"]'
        );
        if (emailInput) {
            const domain = this.getEmailDomain(this.email);
            if (FREE_EMAIL_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        // ---- Step 2: report validity on EVERY input ----
        const inputs = this.template.querySelectorAll('lightning-input');
        let allValid = true;
        inputs.forEach((input) => {
            input.reportValidity();
            if (input.checkValidity() !== true) {
                allValid = false;
            }
        });

        // ---- Step 3: stop when anything is invalid ----
        if (!allValid) {
            return;
        }

        this.isSubmitting = true;
        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            // ---- Step 4a: success toast ----
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success',
                    message: 'Your registration is confirmed.'
                })
            );
        } catch (error) {
            // ---- Step 4b: error toast ----
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    variant: 'error',
                    message: error.body.message
                })
            );
        } finally {
            this.isSubmitting = false;
        }
    }

    /**
     * Returns the lower-cased domain of an email address ('' when it has no '@').
     */
    getEmailDomain(email) {
        const value = (email || '').trim().toLowerCase();
        const atIndex = value.lastIndexOf('@');
        return atIndex === -1 ? '' : value.substring(atIndex + 1);
    }
}
