import { LightningElement, api, track } from 'lwc';

/**
 * statusListbox
 *
 * Single-select listbox following the WAI-ARIA listbox pattern:
 * DOM focus stays on the <ul> (tabindex="0"); the "active" option is only
 * referenced through aria-activedescendant.
 *
 * Two independent states are maintained:
 *  - value        : the selected option (controlled by the parent or by the user)
 *  - _activeValue : the option pointed at by the keyboard / last click
 *
 * Arrow keys only move the active option, Enter/Space (and clicks) change the
 * selection and emit a `change` event - but only when the selection really
 * changes.
 */
export default class StatusListbox extends LightningElement {
    /** Accessible name of the listbox; rendered as aria-label on the <ul>. */
    @api label;

    /**
     * Reactive projection handed to the template:
     * [{ value, label, id, selected, ariaSelected }].
     * It is re-created on every state change, which also triggers the rerender.
     */
    @track renderedOptions = [];

    /** id of the active option; referenced by aria-activedescendant. */
    activeOptionId = null;

    /** Options exactly as supplied by the consumer: [{ value, label }]. */
    _rawOptions = [];

    /** Currently selected value; '' when nothing is selected. */
    _value = '';

    /** Value of the active option; undefined until it can be resolved. */
    _activeValue;

    /** Cached index of the active option (-1 when there is no option). */
    _activeIndex = -1;

    /** Unique prefix so ids never collide between several instances. */
    _idPrefix = `statusListbox-${Math.random().toString(36).slice(2, 10)}`;

    /* ------------------------------------------------------------------ */
    /* Public API                                                          */
    /* ------------------------------------------------------------------ */

    @api
    get options() {
        return this._rawOptions;
    }

    set options(value) {
        this._rawOptions = Array.isArray(value) ? value : [];
        this._refresh();
    }

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        const next = newValue == null ? '' : newValue;
        if (next === this._value) {
            return;
        }
        this._value = next;
        // Whenever the parent changes the value, the active option moves to it.
        this._activeValue = next;
        this._refresh();
    }

    /* ------------------------------------------------------------------ */
    /* Event handlers                                                      */
    /* ------------------------------------------------------------------ */

    /**
     * Keyboard support on the list itself. Only the six supported keys are
     * consumed; every other key (Tab in particular) keeps its default action.
     */
    handleKeydown(event) {
        const { key } = event;
        const options = this._rawOptions;
        const count = options.length;
        const activeIndex = this._activeIndex;

        switch (key) {
            case 'ArrowDown':
                // Move one option down, stop at the last option (no wrap-around).
                if (count > 0) {
                    this._setActiveIndex(Math.min(activeIndex + 1, count - 1));
                }
                break;
            case 'ArrowUp':
                // Move one option up, stop at the first option (no wrap-around).
                if (count > 0) {
                    this._setActiveIndex(Math.max(activeIndex - 1, 0));
                }
                break;
            case 'Home':
                if (count > 0) {
                    this._setActiveIndex(0);
                }
                break;
            case 'End':
                if (count > 0) {
                    this._setActiveIndex(count - 1);
                }
                break;
            case 'Enter':
            case ' ':
                // Selecting never moves the selection by itself via arrows,
                // so it happens only on these two keys.
                if (count > 0 && activeIndex >= 0) {
                    this._select(options[activeIndex].value);
                }
                break;
            default:
                // Everything else - Tab, Escape, printable characters, ...
                // must keep its default behaviour.
                return;
        }

        // Reached only for the six keys handled above.
        event.preventDefault();
    }

    /** Clicking an option selects it and makes it the active option. */
    handleOptionClick(event) {
        const optionElement = event.currentTarget;
        const option = this._rawOptions.find(
            (candidate) => String(candidate.value) === optionElement.dataset.value
        );
        if (option) {
            this._select(option.value);
        }
        // DOM focus stays on the list itself.
        const listbox = this.template.querySelector('[role="listbox"]');
        if (listbox) {
            listbox.focus();
        }
    }

    /* ------------------------------------------------------------------ */
    /* Internals                                                           */
    /* ------------------------------------------------------------------ */

    /** Selects `value`, makes it active and emits `change` when it changed. */
    _select(value) {
        const changed = value !== this._value;
        this._activeValue = value;
        if (changed) {
            this._value = value;
        }
        this._refresh();
        if (changed) {
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value },
                    bubbles: true,
                    composed: true,
                })
            );
        }
    }

    /** Makes the option at `index` the active one; the selection is untouched. */
    _setActiveIndex(index) {
        const option = this._rawOptions[index];
        if (!option) {
            return;
        }
        this._activeValue = option.value;
        this._refresh();
    }

    /**
     * Rebuilds the template projection: generated ids, aria-selected flags and
     * the id of the active option (falling back to the selected option, then to
     * the first one).
     */
    _refresh() {
        const options = this._rawOptions.map((option, index) => {
            const source = option || {};
            return {
                value: source.value,
                label: source.label,
                id: `${this._idPrefix}-option-${index}`,
            };
        });

        const selectedIndex = options.findIndex((option) => option.value === this._value);
        let activeIndex = options.findIndex((option) => option.value === this._activeValue);
        if (activeIndex < 0) {
            // No active option yet (or it disappeared from the list):
            // the selected option wins, otherwise the first one.
            activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
        }

        this._activeIndex = options.length > 0 ? activeIndex : -1;
        this.renderedOptions = options.map((option, index) => ({
            ...option,
            selected: index === selectedIndex,
            ariaSelected: index === selectedIndex ? 'true' : 'false',
        }));
        this.activeOptionId = this._activeIndex >= 0 ? options[this._activeIndex].id : null;
    }
}
