import { LightningElement, api } from 'lwc';

/**
 * Module-scoped counter so that generated ids are unique across every
 * instance of the component on the page, not just within one instance.
 */
let generatedIdCounter = 0;

function generateUniqueId(existingIds) {
    let id;
    do {
        generatedIdCounter += 1;
        id = `new-${generatedIdCounter}`;
    } while (existingIds.has(id));
    return id;
}

export default class TaskChecklist extends LightningElement {
    /**
     * Display-only value supplied by the parent. It is never written to, so the
     * parent's value is preserved and any later change from the parent re-renders.
     */
    @api heading;

    /** Reference to the array the parent passed in. Never mutated. */
    _tasks = [];

    /** The component's own working copy of the task list. */
    items = [];

    newLabel = '';

    /**
     * Public `tasks` property. Every assignment from the parent replaces the
     * working list with a fresh copy, so neither the parent's array nor the
     * parent's task objects are ever modified.
     */
    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = Array.isArray(value) ? value : [];
        this.items = this._tasks.map((task) => ({ ...task }));
    }

    /** Uppercased heading used only for rendering. */
    get headingText() {
        if (this.heading === undefined || this.heading === null) {
            return '';
        }
        return String(this.heading).toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = typeof this.newLabel === 'string' ? this.newLabel.trim() : '';
        if (!label) {
            return;
        }

        const existingIds = new Set(this.items.map((task) => String(task.id)));
        const id = generateUniqueId(existingIds);

        // Reassign the array so the change is reactive and re-renders.
        this.items = [...this.items, { id, label, done: false }];

        this.newLabel = '';

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true,
            })
        );
    }

    handleToggle(event) {
        const target = event.target;
        const id = target && target.dataset ? target.dataset.id : undefined;
        if (id === undefined) {
            return;
        }

        const index = this.items.findIndex((task) => String(task.id) === id);
        if (index === -1) {
            return;
        }

        const task = this.items[index];
        // Replace the item (and the array) instead of mutating in place.
        this.items = [
            ...this.items.slice(0, index),
            { ...task, done: !task.done },
            ...this.items.slice(index + 1),
        ];
    }
}
