/**
 * Converts an existing open donation (pledge) into a monthly installment plan.
 *
 * The service is deliberately written so that every business rule is evaluated
 * *before* any DML happens: if the request is invalid, nothing in the org is
 * changed and a PaymentPlanException is thrown instead.
 *
 * Behaviour:
 *   - Paid and written-off payments are history and are never modified or deleted.
 *   - All other payments (unpaid and not written off) are deleted and replaced by
 *     `numberOfPayments` new unpaid payments.
 *   - Payment i (0-based) is scheduled on firstPaymentDate.addMonths(i).
 *   - Outstanding amount = Opportunity.Amount - sum(paid/written-off payment amounts).
 *   - Each payment receives outstanding / numberOfPayments rounded DOWN to the cent;
 *     the last payment absorbs the remainder so the plan sums exactly to outstanding.
 *
 * All reads and writes run in user mode (sharing rules, CRUD and FLS enforced).
 */
public with sharing class PaymentPlanService {

    /** Thrown when the installment request is invalid or cannot be fulfilled. */
    public class PaymentPlanException extends Exception {}

    /**
     * Schedules an installment plan for an opportunity.
     *
     * @param opportunityId      the pledge / opportunity to convert
     * @param numberOfPayments   number of installments to create (>= 1, not null)
     * @param firstPaymentDate   scheduled date of the first installment
     * @return the newly inserted payments, in schedule order
     * @throws PaymentPlanException if the request is invalid; nothing is changed in that case
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // -------------------------------------------------------------------------
        // 1. Validation - performed entirely before any DML.
        // -------------------------------------------------------------------------
        if (opportunityId == null) {
            throw new PaymentPlanException('An Opportunity Id is required.');
        }
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be at least 1 and cannot be null.'
            );
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('firstPaymentDate is required.');
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new PaymentPlanException(
                'Opportunity ' + String.valueOf(opportunityId) +
                ' was not found or is not accessible.'
            );
        }
        Opportunity opportunityRecord = opportunities[0];

        if (opportunityRecord.IsClosed) {
            throw new PaymentPlanException(
                'Installments can only be scheduled on an open opportunity.'
            );
        }

        // -------------------------------------------------------------------------
        // 2. Read the existing payments and split them into history vs. replaceable.
        // -------------------------------------------------------------------------
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Opportunity__c,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];

        Decimal settledAmount = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : existingPayments) {
            Decimal paymentAmount =
                payment.npe01__Payment_Amount__c == null ? 0 : payment.npe01__Payment_Amount__c;

            Boolean isSettled =
                payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true;

            if (isSettled) {
                // Paid and written-off payments are history: leave them untouched,
                // but their value has already been settled against the pledge.
                settledAmount += paymentAmount;
            } else {
                // Unpaid and not written off: this is what the plan replaces.
                paymentsToDelete.add(payment);
            }
        }

        // -------------------------------------------------------------------------
        // 3. Outstanding amount validation.
        // -------------------------------------------------------------------------
        Decimal opportunityAmount =
            opportunityRecord.Amount == null ? 0 : opportunityRecord.Amount;
        Decimal outstandingAmount = opportunityAmount - settledAmount;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException(
                'The outstanding amount must be greater than zero (Opportunity Amount ' +
                String.valueOf(opportunityAmount) + ' less settled payments ' +
                String.valueOf(settledAmount) + ').'
            );
        }

        // -------------------------------------------------------------------------
        // 4. Build the new installment schedule.
        // -------------------------------------------------------------------------
        Decimal paymentCount = numberOfPayments;
        Decimal unitAmount = outstandingAmount.divide(paymentCount, 2, RoundingMode.DOWN);

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        Decimal alreadyScheduled = 0;

        for (Integer i = 0; i < numberOfPayments; i++) {
            Boolean isLastPayment = (i == numberOfPayments - 1);

            Decimal amountForThisPayment;
            if (isLastPayment) {
                // Last installment absorbs the rounding remainder so the plan
                // sums exactly to the outstanding amount.
                amountForThisPayment = outstandingAmount - alreadyScheduled;
            } else {
                amountForThisPayment = unitAmount;
            }
            alreadyScheduled += amountForThisPayment;

            newPayments.add(
                new npe01__OppPayment__c(
                    npe01__Opportunity__c = opportunityId,
                    npe01__Payment_Amount__c = amountForThisPayment,
                    npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                    npe01__Paid__c = false,
                    npe01__Written_Off__c = false
                )
            );
        }

        // -------------------------------------------------------------------------
        // 5. DML - only reached when every validation above has passed.
        // -------------------------------------------------------------------------
        if (!paymentsToDelete.isEmpty()) {
            Database.delete(paymentsToDelete, AccessLevel.USER_MODE);
        }
        Database.insert(newPayments, AccessLevel.USER_MODE);

        // The inserted records have their Ids populated and remain in schedule order.
        return newPayments;
    }
}
