/**
 * GiftService - records gifts that have already been received, the way NPSP expects them.
 *
 * Every call writes one complete gift in a single transaction:
 *   - an Opportunity on the donor contact's Household Account, StageName 'Closed Won',
 *     CloseDate = giftDate and npsp__Primary_Contact__c = the donor contact;
 *   - one OpportunityContactRole for every contact of that household: 'Donor' (primary) for
 *     the gifting contact, 'Household Member' for everybody else - a contact never receives
 *     more than one contact role on the gift;
 *   - exactly one npe01__OppPayment__c, paid, for the full amount, dated giftDate (NPSP may
 *     have auto-created a payment when the Opportunity was inserted - it is reused instead
 *     of creating a duplicate).
 *
 * All reads/writes are set based (no SOQL or DML inside a loop), so the class is safe to
 * call repeatedly within the same transaction, and any failure leaves the transaction to
 * roll back as a whole (no exceptions are swallowed).
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON      = 'Closed Won';
    private static final String ROLE_DONOR            = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a gift that has already been received.
     *
     * @param contactId the contact the gift comes from (must exist and belong to a household account)
     * @param amount    gift amount, must be greater than zero
     * @param giftDate  date the gift was received (also the opportunity close date and payment date)
     * @return the Id of the created Opportunity
     * @throws IllegalArgumentException when the contact does not exist or the amount is null, zero or negative
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {

        // ---------------- validation ----------------------------------------
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('The gift amount must be greater than zero.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('A contact Id is required to record a gift.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('A gift date is required to record a gift.');
        }

        Contact donor = getDonor(contactId);           // throws when the contact does not exist
        List<Contact> household = getHousehold(donor); // donor + every other household member

        // ---------------- the gift ------------------------------------------
        Opportunity gift = new Opportunity(
            Name = buildGiftName(donor, giftDate),
            AccountId = donor.AccountId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON,
            npsp__Primary_Contact__c = donor.Id
        );
        insert gift;

        // ---------------- NPSP contact roles --------------------------------
        syncContactRoles(gift.Id, donor.Id, household);

        // ---------------- the single payment --------------------------------
        syncPayment(gift.Id, amount, giftDate);

        return gift.Id;
    }

    // -------------------------------------------------------------------------
    // helpers
    // -------------------------------------------------------------------------

    /** Returns the donor contact, or throws IllegalArgumentException when it does not exist. */
    private static Contact getDonor(Id contactId) {
        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact ' + contactId + ' does not exist.');
        }

        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' is not related to a Household Account and cannot be given a gift.'
            );
        }
        return donor;
    }

    /** Returns every contact of the donor's household account, de-duplicated, donor included. */
    private static List<Contact> getHousehold(Contact donor) {
        List<Contact> household = [
            SELECT Id, FirstName, LastName
            FROM Contact
            WHERE AccountId = :donor.AccountId
            ORDER BY Id
        ];

        Set<Id> seen = new Set<Id>();
        List<Contact> unique = new List<Contact>();
        for (Contact member : household) {
            if (member != null && member.Id != null && seen.add(member.Id)) {
                unique.add(member);
            }
        }
        // defensive: the donor is always part of its own household
        if (!seen.contains(donor.Id)) {
            unique.add(donor);
        }
        return unique;
    }

    /** '<FirstName> <LastName> Donation <yyyy-MM-dd>' - e.g. 'Jane Smith Donation 2026-03-01'. */
    private static String buildGiftName(Contact donor, Date giftDate) {
        String firstName = donor.FirstName == null ? '' : donor.FirstName.trim();
        String lastName = donor.LastName == null ? '' : donor.LastName.trim();
        String fullName = (firstName + ' ' + lastName).trim();
        // String.valueOf(Date) renders ISO 'yyyy-MM-dd'
        return fullName + ' Donation ' + String.valueOf(giftDate);
    }

    /**
     * Creates/normalises exactly one contact role per household contact:
     * 'Donor' + primary for the gifting contact, 'Household Member' for everyone else.
     * Roles that already exist (e.g. created by an NPSP trigger) are updated, never duplicated.
     */
    private static void syncContactRoles(Id giftId, Id donorId, List<Contact> household) {
        Map<Id, OpportunityContactRole> roleByContactId = new Map<Id, OpportunityContactRole>();
        for (OpportunityContactRole existingRole : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :giftId
        ]) {
            // a contact keeps at most one role on this gift
            if (!roleByContactId.containsKey(existingRole.ContactId)) {
                roleByContactId.put(existingRole.ContactId, existingRole);
            }
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        Set<Id> handled = new Set<Id>();

        for (Contact member : household) {
            if (member == null || member.Id == null || !handled.add(member.Id)) {
                continue;
            }

            Boolean isDonor = (member.Id == donorId);
            String desiredRole = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER;
            Boolean desiredPrimary = isDonor;

            OpportunityContactRole existingRole = roleByContactId.get(member.Id);
            if (existingRole == null) {
                rolesToInsert.add(
                    new OpportunityContactRole(
                        OpportunityId = giftId,
                        ContactId = member.Id,
                        Role = desiredRole,
                        IsPrimary = desiredPrimary
                    )
                );
            } else if (existingRole.Role != desiredRole || existingRole.IsPrimary != desiredPrimary) {
                existingRole.Role = desiredRole;
                existingRole.IsPrimary = desiredPrimary;
                rolesToUpdate.add(existingRole);
            }
        }

        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

    /**
     * Guarantees exactly one payment on the gift: paid, for the full amount, dated giftDate.
     * If NPSP auto-created a payment when the Opportunity was inserted, that record is reused
     * and any surplus payment is removed, so no duplicate payments are left behind.
     */
    private static void syncPayment(Id giftId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :giftId
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = giftId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        npe01__OppPayment__c payment = payments[0];
        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c = true;
        update payment;

        List<npe01__OppPayment__c> duplicates = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < payments.size(); i++) {
            duplicates.add(payments[i]);
        }
        if (!duplicates.isEmpty()) {
            delete duplicates;
        }
    }
}
