```apex
/**
 * Read-only service that answers, for a set of record Ids, which ones the running user
 * is actually allowed to edit.
 *
 * The answer comes from the UserRecordAccess object, which reports the *effective* access
 * the running user has on each record after Salesforce has already applied:
 *   - object and field CRUD/FLS permissions,
 *   - record ownership,
 *   - the org-wide defaults plus manual/theater sharing rules,
 *   - the role hierarchy (parents see children),
 *   - the "View All" / "Modify All" profile and permission-set permissions,
 *   - territory/managed sharing, etc.
 *
 * Because UserRecordAccess performs that evaluation for us, this class deliberately does
 * NOT re-implement sharing rules, does not query the record rows themselves (so it needs no
 * read access to the underlying objects and never exposes record data), and does not need
 * Security.stripInaccessible: only RecordId and HasEditAccess from a system access object
 * are read, and the whole point of the call is to filter the caller's Id list.
 *
 * Class is `with sharing` so it stays safe if it ever gains queries against regular sObjects.
 *
 * Nothing is written, there is no per-record query, and no static state is cached: access is
 * recomputed on every call so a caller can never be handed a stale verdict from earlier in
 * the transaction after sharing has changed.
 */
public with sharing class RecordAccessService {

    /**
     * UserRecordAccess SOQL statements are restricted in how many record Ids they may cover,
     * and this method is given a hard budget of 20 SOQL queries for the documented maximum
     * input of 2,000 Ids: 2,000 / 20 = 100 Ids per statement. Any larger chunk risks either
     * the per-statement cap or blowing the transaction query budget shared with other logic.
     */
    private static final Integer MAX_IDS_PER_QUERY = 100;

    /**
     * Returns the subset of recordIds the running user can edit.
     *
     * @param recordIds Ids to evaluate; may be null, empty, contain nulls, and may mix objects.
     * @return Never null. The subset of recordIds for which UserRecordAccess.HasEditAccess is true.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        // Never return null, and never run a query for nothing.
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Drop nulls/invalid entries defensively so the Id list built below is always usable.
        Set<Id> candidates = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                candidates.add(recordId);
            }
        }
        if (candidates.isEmpty()) {
            return editable;
        }

        // Set -> List gives a stable, de-duplicated sequence we can slice into chunks.
        List<Id> allIds = new List<Id>(candidates);
        Id runningUserId = UserInfo.getUserId();

        for (Integer startIndex = 0;
             startIndex < allIds.size();
             startIndex += MAX_IDS_PER_QUERY) {

            Integer endIndex = Math.min(startIndex + MAX_IDS_PER_QUERY, allIds.size());

            Set<Id> chunk = new Set<Id>();
            for (Integer i = startIndex; i < endIndex; i++) {
                chunk.add(allIds[i]);
            }

            // One query per chunk, always scoped to the running user (required by the object)
            // and to a bounded set of RecordIds. Ids from different objects are fine here.
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE RecordId IN :chunk
                  AND UserId = :runningUserId
            ]) {
                // Only explicitly granted edit access is reported; records with no row, or a
                // row with HasEditAccess = false, are left out of the result.
                if (access.HasEditAccess) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
