/**
 * ContactImportService
 *
 * Handles insertion of Contacts that are being migrated from the legacy system.
 *
 * These records must:
 *   - still run ALL other Contact automation (e.g. TA_Contact_FormatPhone, validation rules,
 *     assignment rules, other TAF actions), and
 *   - skip exactly one Trigger Actions Framework action: TA_Contact_CreateWelcomeTask
 *     (because existing customers must not receive a "Send welcome pack" Task).
 *
 * The bypass is scoped to the single action name - it does NOT use
 * TriggerBase.bypass('Contact'), which would disable the whole framework for the object
 * (including the phone formatting action). It is applied immediately before the DML and
 * released in a `finally` block, so it is never leaked to contacts inserted later in the
 * same transaction, even when the insert throws.
 *
 * Bulk-safe: the records are inserted with one DML statement, regardless of list size.
 */
public with sharing class ContactImportService {
	/** Fully qualified name of the single TAF action to skip for migrated contacts. */
	private static final String SKIP_WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

	/**
	 * Inserts the supplied contacts in one DML statement with the
	 * TA_Contact_CreateWelcomeTask action bypassed. Every other Contact automation
	 * (TAF actions, triggers, flows, validation rules, ...) runs normally.
	 *
	 * When this method returns - successfully or not - the bypass is no longer active.
	 *
	 * @param contacts the Contact records to insert; null/empty input is a no-op.
	 * @throws DmlException forwarded from the single insert statement (bypass is still cleared).
	 */
	public static void importContacts(List<Contact> contacts) {
		if (contacts == null || contacts.isEmpty()) {
			return;
		}

		try {
			// Scope the bypass to one action name so all other Contact automation still runs.
			MetadataTriggerHandler.bypass(SKIP_WELCOME_TASK_ACTION);
			insert contacts;
		} finally {
			// Always release the bypass - even if the DML fails - so that contacts
			// inserted later in this transaction still get their welcome task.
			MetadataTriggerHandler.clearBypass(SKIP_WELCOME_TASK_ACTION);
		}
	}
