public with sharing class TA_Opportunity_CollectForErpSync implements
	TriggerAction.AfterInsert,
	TriggerAction.AfterUpdate
{
	/*
	 * Ids of the opportunities that have to be pushed to the ERP for the DML
	 * operation that is currently being processed.
	 *
	 * This state MUST be static:
	 *  - MetadataTriggerHandler instantiates this class once per trigger
	 *    invocation, so instance state would be lost between the 200 + 50 chunks
	 *    of a single 250 row insert;
	 *  - static state survives every chunk of one DML operation, so all 250 Ids
	 *    are available when OpportunityErpSyncFinalizer runs once for that
	 *    operation;
	 *  - the finalizer drains this collection, so the next DML operation of the
	 *    same transaction starts from an empty collection (two DML statements in
	 *    one transaction therefore produce two independent jobs).
	 */
	private static Set<Id> idsToSync = new Set<Id>();

	public void afterInsert(List<SObject> triggerNew) {
		// Every opportunity must be pushed to the ERP when it is created.
		for (SObject currentRecord : triggerNew) {
			idsToSync.add(((Opportunity) currentRecord).Id);
		}
	}

	public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
		// Only opportunities whose StageName changed have to be pushed to the ERP.
		for (Integer i = 0; i < triggerNew.size(); i++) {
			Opportunity newRecord = (Opportunity) triggerNew[i];
			Opportunity oldRecord = (Opportunity) triggerOld[i];
			if (newRecord.StageName != oldRecord.StageName) {
				idsToSync.add(newRecord.Id);
			}
		}
	}

	/**
	 * Returns a snapshot of the Ids collected for the current DML operation.
	 * The caller is responsible for clearing the collection (via
	 * clearIdsToSync()) so that the next DML operation starts from scratch.
	 */
	public static Set<Id> getIdsToSync() {
		return new Set<Id>(idsToSync);
	}

	/** Resets the collection once the DML operation has been flushed. */
	public static void clearIdsToSync() {
		idsToSync.clear();
	}
}
