@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    // ---------------------------------------------------------------------
    // Helpers: build records entirely in memory, no DML, no SOQL.
    // ---------------------------------------------------------------------

    private static Opportunity buildRecord(
        Decimal oldAmount,
        Decimal newAmount,
        Boolean withId
    ) {
        Id recordId = withId
            ? TriggerTestUtility.getFakeId(Opportunity.SObjectType)
            : null;
        Opportunity oldRecord = new Opportunity(
            Id = recordId,
            Amount = oldAmount
        );
        Opportunity newRecord = new Opportunity(
            Id = recordId,
            Amount = newAmount
        );
        // Stash the "old" value so the caller can pair it up.
        newRecord.put('Description', null);
        return oldRecord;
    }

    private static List<Opportunity> makeOld(List<Opportunity> records) {
        List<Opportunity> oldList = new List<Opportunity>();
        for (Opportunity opp : records) {
            oldList.add(
                new Opportunity(
                    Id = opp.Id,
                    Amount = opp.Amount
                )
            );
        }
        return oldList;
    }

    private static void assertExactlyOneError(Opportunity opp) {
        System.assertEquals(
            true,
            opp.hasErrors(),
            'Expected an error on the record.'
        );
        List<Database.Error> errors = opp.getErrors();
        System.assertEquals(
            1,
            errors.size(),
            'Expected exactly one error, found ' + errors.size() + '.'
        );
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Error message did not match the action constant.'
        );
        System.assertEquals(
            StatusCode.FIELD_CUSTOM_VALIDATION_EXCEPTION,
            errors[0].getStatusCode(),
            'Expected a custom validation error status code.'
        );
    }

    private static void assertNoError(Opportunity opp) {
        System.assertEquals(
            false,
            opp.hasErrors(),
            'Expected no error on the record.'
        );
        System.assertEquals(
            0,
            opp.getErrors().size(),
            'Expected zero errors on the record.'
        );
    }

    // ---------------------------------------------------------------------
    // 1. A reduction of more than half is rejected with exactly one error.
    // ---------------------------------------------------------------------
    @IsTest
    static void rejectsReductionOfMoreThanHalf() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(Id = fakeId, Amount = 499)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = fakeId, Amount = 1000)
        };

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();

        assertExactlyOneError(triggerNew[0]);
    }

    // ---------------------------------------------------------------------
    // 2. A reduction of exactly half is accepted.
    // 3. An increase is accepted.
    // ---------------------------------------------------------------------
    @IsTest
    static void acceptsExactlyHalfReductionAndIncrease() {
        Id fakeIdHalf = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id fakeIdIncrease = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(Id = fakeIdHalf, Amount = 500),
            new Opportunity(Id = fakeIdIncrease, Amount = 2500)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = fakeIdHalf, Amount = 1000),
            new Opportunity(Id = fakeIdIncrease, Amount = 2000)
        };

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();

        assertNoError(triggerNew[0]);
        assertNoError(triggerNew[1]);
    }

    // ---------------------------------------------------------------------
    // 4. A record whose previous Amount was null is accepted without an exception.
    // ---------------------------------------------------------------------
    @IsTest
    static void acceptsNullPreviousAmount() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(Id = fakeId, Amount = 100)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = fakeId, Amount = null)
        };

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();

        assertNoError(triggerNew[0]);
    }

    // ---------------------------------------------------------------------
    // 5. Mixed batch: only the offending records receive the error.
    // ---------------------------------------------------------------------
    @IsTest
    static void flagsOnlyOffendingRecordsInMixedCall() {
        Id idViolation = TriggerTestUtility.getFakeId(Opportunity.SObjectType);   // 1000 -> 499 : violation
        Id idExactHalf = TriggerTestUtility.getFakeId(Opportunity.SObjectType);   // 1000 -> 500 : ok
        Id idIncrease = TriggerTestUtility.getFakeId(Opportunity.SObjectType);    // 1000 -> 9000: ok
        Id idNullOld = TriggerTestUtility.getFakeId(Opportunity.SObjectType);     // null -> 1   : ok
        Id idViolation2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);  // 60 -> 29    : violation

        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(Id = idViolation, Amount = 499),
            new Opportunity(Id = idExactHalf, Amount = 500),
            new Opportunity(Id = idIncrease, Amount = 9000),
            new Opportunity(Id = idNullOld, Amount = 1),
            new Opportunity(Id = idViolation2, Amount = 29)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = idViolation, Amount = 1000),
            new Opportunity(Id = idExactHalf, Amount = 1000),
            new Opportunity(Id = idIncrease, Amount = 1000),
            new Opportunity(Id = idNullOld, Amount = null),
            new Opportunity(Id = idViolation2, Amount = 60)
        };

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();

        assertExactlyOneError(triggerNew[0]);
        assertNoError(triggerNew[1]);
        assertNoError(triggerNew[2]);
        assertNoError(triggerNew[3]);
        assertExactlyOneError(triggerNew[4]);

        // Only two of the five records may be flagged.
        Integer flagged = 0;
        for (Opportunity opp : triggerNew) {
            if (opp.hasErrors()) {
                flagged++;
            }
        }
        System.assertEquals(2, flagged, 'Exactly the two violating records should be flagged.');
    }
}
