/**
 * Trigger Action (before insert / before update) for the Trigger Actions Framework
 * (TAF 0.3.4, unlocked package, no namespace).
 *
 * Business rule: two Contacts belonging to the same Account may not share the same
 * email address. The comparison is case-insensitive. Contacts without an Account and
 * contacts without an Email are never checked.
 *
 * Behaviour:
 *  - Each violating record receives a record-level error via addError, so valid
 *    records in the same save are unaffected (partial saves keep working).
 *  - Within a single save, contacts claiming the same (Account, Email) pair are
 *    processed in list order: the first one is accepted, every later one is rejected.
 *  - On update only contacts whose Email or AccountId changed are evaluated, so
 *    pre-existing (legacy) duplicates never block unrelated edits, and a contact is
 *    never compared against itself.
 *  - Bulk safe: at most one SOQL query is executed per trigger invocation.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforceRule(toContacts(triggerNew), null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        enforceRule(toContacts(triggerNew), toContacts(triggerOld));
    }

    private static void enforceRule(
        List<Contact> newContacts,
        List<Contact> oldContacts
    ) {
        Boolean isUpdate = oldContacts != null;
        Set<Id> accountIdsToCheck = new Set<Id>();
        Set<Id> changedContactIds = new Set<Id>();
        List<Integer> indexesToCheck = new List<Integer>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact newContact = newContacts[i];

            if (isUpdate) {
                Contact oldContact = oldContacts[i];
                Boolean emailChanged = newContact.Email != oldContact.Email;
                Boolean accountChanged = newContact.AccountId != oldContact.AccountId;
                if (!emailChanged && !accountChanged) {
                    // Nothing relevant changed: never re-validate legacy duplicates.
                    continue;
                }
                // Its persisted row is superseded by its in-memory state below,
                // so it must be excluded from the "existing duplicates" query.
                changedContactIds.add(newContact.Id);
            }

            if (isCheckable(newContact)) {
                indexesToCheck.add(i);
                accountIdsToCheck.add(newContact.AccountId);
            }
        }

        if (indexesToCheck.isEmpty()) {
            return;
        }

        // Exactly one SOQL query for the whole trigger execution.
        Set<String> claimedKeys = getExistingKeys(accountIdsToCheck, changedContactIds);

        // Iterate in trigger list order: the first record claiming a key wins,
        // every later record with the same key is rejected.
        for (Integer index : indexesToCheck) {
            Contact contactToCheck = newContacts[index];
            String key = buildKey(contactToCheck.AccountId, contactToCheck.Email);
            if (claimedKeys.contains(key)) {
                contactToCheck.addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                claimedKeys.add(key);
            }
        }
    }

    /**
     * Reads the emails already persisted on the involved accounts, so that the
     * in-save evaluation is compared against real data. Contacts that are part of
     * the current (update) transaction are excluded: their in-memory state is
     * evaluated separately, which also prevents a contact conflicting with itself.
     */
    private static Set<String> getExistingKeys(
        Set<Id> accountIds,
        Set<Id> contactIdsToExclude
    ) {
        Set<String> keys = new Set<String>();
        List<Contact> existingContacts;

        if (contactIdsToExclude.isEmpty()) {
            existingContacts = [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                AND Email != null
            ];
        } else {
            existingContacts = [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                AND Email != null
                AND Id NOT IN :contactIdsToExclude
            ];
        }

        for (Contact existingContact : existingContacts) {
            if (isCheckable(existingContact)) {
                keys.add(buildKey(existingContact.AccountId, existingContact.Email));
            }
        }
        return keys;
    }

    private static Boolean isCheckable(Contact contactRecord) {
        return contactRecord.AccountId != null && String.isNotBlank(contactRecord.Email);
    }

    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + ':' + email.trim().toLowerCase();
    }

    private static List<Contact> toContacts(List<SObject> records) {
        if (records == null) {
            return null;
        }
        List<Contact> contacts = new List<Contact>();
        for (SObject record : records) {
            contacts.add((Contact) record);
        }
        return contacts;
    }
}
