public with sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
	public void beforeInsert(List<SObject> triggerNew) {
		if (triggerNew == null || triggerNew.isEmpty()) {
			return;
		}
		for (SObject sob : triggerNew) {
			Lead ld = (Lead) sob;
			if (String.isNotBlank(ld.Email)) {
				ld.Email = ld.Email.trim().toLowerCase();
			} else if (ld.Email != null && String.isBlank(ld.Email)) {
				// Whitespace-only email: normalize to null so it stays clean.
				ld.Email = null;
			}
			if (ld.Company != null) {
				ld.Company = ld.Company.trim();
			}
			if (String.isBlank(ld.LeadSource)) {
				ld.LeadSource = 'Web';
			}
		}
	}
}
