/**
 * Trigger Action that keeps Account.FB_Open_Case_Count__c equal to the number of Cases of
 * the account whose IsClosed flag is false.
 *
 * It is registered with the Trigger Actions Framework through the Trigger_Action__mdt
 * records TA_Case_RollupOpenCount_AI (after insert), _AU (after update), _AD (after delete)
 * and _AUD (after undelete), all with Order__c = 10, on CaseTrigger.
 *
 * Governor limits per trigger execution: ONE aggregate SOQL query and ONE DML statement,
 * no matter how many Cases (up to the 200 record trigger batch size) are processed.
 *
 * Declared "without sharing" on purpose: the stored counter has to reflect every open Case
 * of the account, including the ones the running user cannot see through sharing rules.
 */
public without sharing class TA_Case_RollupOpenCount
	implements TriggerAction.AfterInsert,
		TriggerAction.AfterUpdate,
		TriggerAction.AfterDelete,
		TriggerAction.AfterUndelete {

	public void afterInsert(List<SObject> triggerNew) {
		rollupOpenCaseCount(affectedAccountIds(triggerNew, null));
	}

	public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
		rollupOpenCaseCount(affectedAccountIds(triggerNew, triggerOld));
	}

	public void afterDelete(List<SObject> triggerOld) {
		rollupOpenCaseCount(affectedAccountIds(triggerOld, null));
	}

	public void afterUndelete(List<SObject> triggerNew) {
		rollupOpenCaseCount(affectedAccountIds(triggerNew, null));
	}

	/**
	 * Accounts whose stored count may have changed:
	 *  - insert / delete / undelete: every account referenced by the records;
	 *  - update (oldRecords != null): only the accounts of the cases whose IsClosed flag or
	 *    whose AccountId changed - both the old and the new account, so a case moved between
	 *    two accounts refreshes both sides of the roll-up.
	 * Cases without an account are ignored.
	 */
	private static Set<Id> affectedAccountIds(List<SObject> newRecords, List<SObject> oldRecords) {
		Set<Id> accountIds = new Set<Id>();
		if (oldRecords == null) {
			for (SObject record : newRecords) {
				addAccountId(accountIds, (Id) record.get('AccountId'));
			}
			return accountIds;
		}
		for (Integer index = 0; index < newRecords.size(); index++) {
			SObject newRecord = newRecords[index];
			SObject oldRecord = oldRecords[index];
			Id newAccountId = (Id) newRecord.get('AccountId');
			Id oldAccountId = (Id) oldRecord.get('AccountId');
			Boolean openStateChanged =
				(Boolean) newRecord.get('IsClosed') != (Boolean) oldRecord.get('IsClosed');
			if (openStateChanged || newAccountId != oldAccountId) {
				addAccountId(accountIds, newAccountId);
				addAccountId(accountIds, oldAccountId);
			}
		}
		return accountIds;
	}

	private static void addAccountId(Set<Id> accountIds, Id accountId) {
		if (accountId != null) {
			accountIds.add(accountId);
		}
	}

	/**
	 * Query 1: one aggregate query giving the current number of open Cases per affected
	 * account. In every after context the database already holds the new state, so the
	 * result is correct for insert, update, delete and undelete alike.
	 *
	 * DML 1: a single update statement. Accounts that are missing from the aggregate have
	 * no open Case left and are written as 0, never left blank.
	 */
	private static void rollupOpenCaseCount(Set<Id> accountIds) {
		if (accountIds.isEmpty()) {
			return;
		}
		Map<Id, Integer> openCaseCountByAccountId = new Map<Id, Integer>();
		for (AggregateResult result : [
			SELECT AccountId, COUNT(Id) openCases
			FROM Case
			WHERE IsClosed = false
				AND AccountId IN :accountIds
			GROUP BY AccountId
		]) {
			openCaseCountByAccountId.put(
				(Id) result.get('AccountId'),
				toInteger(result.get('openCases'))
			);
		}
		List<Account> accountsToUpdate = new List<Account>();
		for (Id accountId : accountIds) {
			accountsToUpdate.add(
				new Account(
					Id = accountId,
					FB_Open_Case_Count__c = openCaseCountByAccountId.containsKey(accountId)
						? openCaseCountByAccountId.get(accountId)
						: 0
				)
			);
		}
		update accountsToUpdate;
	}

	/** COUNT() is exposed as an Integer (or Long); normalise instead of blind-casting. */
	private static Integer toInteger(Object aggregateValue) {
		if (aggregateValue instanceof Integer) {
			return (Integer) aggregateValue;
		}
		return aggregateValue == null ? 0 : Integer.valueOf(String.valueOf(aggregateValue));
	}
}
